// Cyrus per-game adapter contract (MASTER-PLAN 4.10). The engine core (lib/cyrus/engine-core) is game-agnostic;
// everything it needs to know about one game comes through this interface. Pure types + data, client-safe.
// Adapter #1 is lib/cyrus/adapters/minecraft.ts. A new game = one new adapter file + a row in adapters/index.ts.
import type { ArtifactRoute, AssetKind } from "../engine-core/spec";
import type { AssetProfile } from "./asset-profile";

/**
 * How far a game's support really goes. Never claim more than ran:
 * planned = nothing built; template = canned preview code only (no compile); beta = real AI build + compile + scan;
 * stable = beta plus boot and functional tests on every build.
 */
export type AdapterMaturity = "planned" | "template" | "beta" | "stable";

/** available = Cyrus produces it today; planned = on the roadmap, not built; unsupported = the game cannot use it. */
export type RouteAvailability = "available" | "planned" | "unsupported";

export type ArtifactType = {
  route: ArtifactRoute;
  availability: RouteAvailability;
  /** File form of the artifact ("jar", "zip", "dll"...). */
  packaging: string;
  side: "server" | "client" | "both";
  /** Customer-voice explanation, shown by the router. */
  note: string;
};

/** A version as the engine core sees it (an adapter maps its own registry rows to this). */
export type AdapterVersion = {
  id: string;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  /** Game-specific capability flags, e.g. "dialogApi". The core only passes them through to router rules. */
  capabilities: readonly string[];
};

export type ToolchainProfile = {
  language: string;
  /** How a build is compiled (or "none" when only linted). */
  compiler: string;
  /** Compiler/runtime release per version, or null when the version is not buildable. */
  releaseFor: (version: string) => string | null;
  /** Where the deny-list / safety scan lives (repo path), so a build record can cite it. */
  scanner: string;
};

export type AssetDelivery = {
  supported: boolean;
  /** How asset files reach players. */
  via: "server-pushed-pack" | "client-zip" | "client-mod" | "server-files" | "none";
  /** available = delivery works today; planned = designed, not built. */
  availability: "available" | "planned" | "none";
  note: string;
};

export type InstallRules = {
  side: "server" | "client" | "both";
  serverPath: string;
  needsRestart: boolean;
  hotReload: boolean;
  summary: string;
};

export type TestLane = {
  compile: boolean;
  scan: boolean;
  /** Boot the real game server with the artifact. */
  boot: "none" | "planned" | "available";
  /** Scripted functional checks (bot, RCON...). */
  functional: "none" | "planned" | "available";
  notes: string;
};

/**
 * One deterministic routing rule. The core router matches `keywords` (lower-case regex sources) against the spec text
 * and prompt; on a match it adds `route` and the honest limit, and checks `requiresCapability` on the target version.
 */
export type RouteRule = {
  id: string;
  keywords: string[];
  /** Asset kinds that trigger this rule without any keyword. */
  assetKinds?: AssetKind[];
  route?: ArtifactRoute;
  requiresCapability?: { capability: string; message: string; /** true = a missing capability is a downgrade (warn), not a block */ downgrade?: boolean;
    /** a weaker capability that still serves the rule (e.g. 1.21.1 legacy custom model data): present = a warn with this message instead of the block */
    fallback?: { capability: string; message: string } };
  /** Build-asset kinds (lib/cyrus/assets/kinds.ts) this rule asks for, when they differ from the spec kinds in assetKinds. */
  buildAssetKinds?: string[];
  /** Shown whenever the rule matches (a fact the user must know: a restart, a client-side limit...). */
  limit?: { severity: "info" | "warn"; message: string };
};

export interface GameAdapter {
  game: string;
  name: string;
  maturity: AdapterMaturity;
  artifacts: readonly ArtifactType[];
  /** The route a request lands on when nothing else is asked for. */
  defaultRoute: ArtifactRoute;
  toolchain: ToolchainProfile;
  /** Where the model's API knowledge for this game lives (two systems exist today, see G-gaps.md (b)). */
  knowledge: { kind: "version-sheets" | "knowledge-pack" | "none"; ref: string };
  versions: {
    list: () => readonly AdapterVersion[];
    get: (id: string) => AdapterVersion | null;
    hasCapability: (id: string, capability: string) => boolean;
  };
  assetDelivery: Readonly<Record<AssetKind, AssetDelivery>>;
  install: InstallRules;
  testLane: TestLane;
  routeRules: readonly RouteRule[];
  /** 3D/texture asset facts (formats, channels, delivery, worker class, legal). Optional: a game without one is text/code only. */
  assetProfile?: AssetProfile;
}
// The game adapters the engine core knows about. Adding a game = one adapter file + one entry here.
import type { GameAdapter } from "./types";
import { minecraftAdapter } from "./minecraft";

export const ADAPTERS: readonly GameAdapter[] = [minecraftAdapter];

export function getAdapter(game: string): GameAdapter | null {
  return ADAPTERS.find((a) => a.game === game) ?? null;
}

export type { GameAdapter } from "./types";
/**
 * The shared contract for per-game modding support in Cyrus (PURE, client-safe, data + types only).
 * Every supported game has ONE file `lib/cyrus/games/<gameId>.ts` default-exporting a `GameSupport`.
 * The studio, the install flow, the lifecycle warnings, the mod store and the marketing page all read
 * from it, so a fact is written once. Facts must be VERIFIED against the loader's own docs/source
 * (cite the URL in `sources`), never guessed. Where something could not be confirmed, say so in `unknowns`.
 */

/** Where a mod's files must be installed for it to work. */
export type InstallSide = "server" | "client" | "both";

export type GameVersionRule = {
  /** Game/server build the mod targets, as the loader labels it ("1.21.4", "v0.4.x", "Build 42"). */
  version: string;
  status: "current" | "supported" | "legacy" | "unsupported";
  /** Loader/framework version needed with this game version ("BepInEx 5.4.2200", "Oxide 2.0.x"). */
  loaderVersion?: string;
  /** What changed that breaks mods from the previous version (so we can warn). */
  breaking?: string[];
};

export type DangerousApi = {
  /** Regex source matched against generated code; a hit blocks the build or forces a warning. */
  pattern: string;
  severity: "block" | "warn";
  why: string;
};

export type FailureRule = {
  id: string;
  /** Regex source run against generated code (or, for kind "compiler-warning"/"runtime", against tool output). */
  detect: string;
  /** Hint injected into the repair prompt. */
  fix: string;
  why: string;
  kind?: "source" | "compiler-warning" | "runtime";
  /** Versions this rule applies to (default: the pack's version). */
  versions?: string[];
  /** True when a deterministic rewrite can fix it without a model turn (see services/modbuilder autofix). */
  autofix?: boolean;
};

export type KnowledgePack = { version: string; apiSheet: string[]; failureRules: FailureRule[] };

/** The (first) knowledge pack of a game, whether it declared one pack or several. */
export function packOf(k: KnowledgePack | KnowledgePack[] | undefined): KnowledgePack | undefined {
  return Array.isArray(k) ? k[0] : k;
}

export type GameSupport = {
  id: string;                    // matches CyrusGame.id in lib/cyrus/games.ts
  name: string;
  /** Plain-language one-liner of what Cyrus builds for this game. */
  builds: string;
  /** Language(s) the mod is written in and the runtime that loads it. */
  language: "Java" | "C#" | "Lua" | "C++" | "JSON/data";
  loader: { name: string; homepage: string; installDocs: string; licenseNote?: string };
  versions: GameVersionRule[];
  /** Where it installs. `reason` is shown to the customer in plain words ("players must also install this"). */
  install: {
    side: InstallSide;
    serverPath: string;          // relative to the game server root
    clientNote?: string;         // what a player must do on their own PC, if side is client/both
    needsRestart: boolean;
    hotReload: boolean;
    packaging: "jar" | "cs-source" | "dll" | "zip" | "lua-folder" | "pak";
    reason: string;
  };
  /** How Cyrus verifies output BEFORE the customer sees it. */
  verification: {
    method: "compile" | "static-lint" | "load-test" | "none";
    notes: string;
    /** Can we run it for real in a sandbox here, or only lint? Be honest. */
    canRunSandbox: boolean;
  };
  dangerousApis: DangerousApi[];
  /** Things that commonly break players' games/servers for this title, with how we avoid them. */
  breakageRisks: { risk: string; guard: string }[];
  /** How a mod becomes "out of date": what signal tells us (game patch, loader update, API removal). */
  outdatedSignals: { signal: string; source: string }[];
  /** Mod categories this game's engine can actually express (ids from lib/cyrus/categories.ts universal set). */
  categories: string[];
  /** Concrete example prompts that work well, for the starter chips. */
  examplePrompts: string[];
  /**
   * Per-game, per-version knowledge pack(s) (optional). One pack per game version (an array when a game supports
   * several, e.g. Minecraft 1.21.x), or a single pack. `apiSheet` lines are VERIFIED API facts for `version`
   * (retrieval injects only the lines for the APIs a plan touches); `failureRules` are known ways generated code
   * breaks on that version. Keep game binaries and decompiled output OUT of git: only the distilled facts go here.
   */
  knowledge?: KnowledgePack | KnowledgePack[];
  sources: string[];             // URLs verified while writing this file
  unknowns: string[];            // honest list of anything not confirmed
};
// Cyrus engine core: ModSpec v1, the typed source of truth of a mod project (MASTER-PLAN 4.1/4.3).
// GAME-AGNOSTIC: nothing here knows any one game. Game facts (versions, which routes and asset kinds a game
// can deliver) come from a GameAdapter (lib/cyrus/adapters) passed in by the caller.
// Pure + client-safe. Zod types in code; `modSpecJsonSchema()` is the portable contract (JSON Schema).
// Every rule failure comes back as a structured issue { path, code, message }, never a thrown error.
import { z } from "zod";
import type { GameAdapter } from "../adapters/types";
import { NAMESPACE_RE } from "./identifiers";
import { ConfigSpecV1Schema, ConfigValueZ, validateConfigSpec } from "../config/spec";
import { checkValues } from "../config/values";

export const CURRENT_SCHEMA_VERSION = 1 as const;

/** What a mod can be built as. Each game adapter says which of these it can really produce. */
export const ARTIFACT_ROUTES = ["plugin", "resourcePack", "dataPack", "clientMod"] as const;
export type ArtifactRoute = (typeof ARTIFACT_ROUTES)[number];

export const ASSET_KINDS = ["texture", "sound", "model", "ui"] as const;
export type AssetKind = (typeof ASSET_KINDS)[number];

/**
 * Where an asset slot's content comes from. generate / library / upload / edit put NEW or CHANGED asset content
 * into the project (plan-gated, lib/cyrus/engine-core/asset-gate.ts); existing / imported keep content the project
 * already holds or brought in with an imported mod (never gated).
 */
export const ASSET_SOURCES = ["generate", "library", "upload", "edit", "existing", "imported"] as const;
export type AssetSource = (typeof ASSET_SOURCES)[number];

export const TEST_KINDS = ["compile", "scan", "boot", "functional", "manual"] as const;

export const REQ_ID_RE = /^REQ-[1-9][0-9]{0,3}$/;
export const TEST_ID_RE = /^T-[1-9][0-9]{0,3}$/;
export const SLOT_ID_RE = /^[a-z][a-z0-9_]{0,47}$/;
export const GAME_ID_RE = /^[a-z][a-z0-9-]{1,31}$/;
/** A catalog asset reference (same pattern as lib/cyrus/library/v2/entry.ts CATALOG_REF_RE). */
export const LIBRARY_REF_RE = /^cat:[0-9a-f]{64}$/;

const line = (max: number) => z.string().trim().min(1).max(max);

const RequirementZ = z.object({
  id: z.string().regex(REQ_ID_RE, "requirement ids are REQ-1, REQ-2, ..."),
  text: z.string().trim().min(3).max(500),
  priority: z.enum(["must", "should", "could"]).default("must"),
}).strict();

const AssetSlotZ = z.object({
  id: z.string().regex(SLOT_ID_RE, "asset ids are lowercase letters, digits and underscores"),
  kind: z.enum(ASSET_KINDS),
  purpose: z.string().trim().min(3).max(300),
  source: z.enum(ASSET_SOURCES).default("generate"),
  /** source "library" only: the catalog asset this slot uses (lib/cyrus/library/v2, `cat:<sha256>`) */
  libraryRef: z.string().regex(LIBRARY_REF_RE, "library refs are cat:<64 hex>").optional(),
  requirementIds: z.array(z.string().regex(REQ_ID_RE)).max(20).default([]),
}).strict();

const TestPlanZ = z.object({
  id: z.string().regex(TEST_ID_RE, "test ids are T-1, T-2, ..."),
  kind: z.enum(TEST_KINDS),
  description: z.string().trim().min(3).max(500),
  covers: z.array(z.string().regex(REQ_ID_RE)).max(50).default([]),
}).strict();

const InstallZ = z.object({
  side: z.enum(["server", "client", "both"]),
  restartRequired: z.boolean(),
  /** What a player must do on their own PC, if anything. */
  clientSteps: z.array(line(300)).max(10).default([]),
  notes: z.array(line(300)).max(10).default([]),
}).strict();

/**
 * The mod's tunable settings (Config and Stats Studio, lib/cyrus/config): the typed schema changes only with a build;
 * `values` are the current values at this revision (a values-only "config" revision changes only these).
 */
const ConfigSectionZ = z.object({ spec: ConfigSpecV1Schema, values: z.record(z.string(), ConfigValueZ).optional() }).strict();

export const ModSpecV1Schema = z.object({
  schemaVersion: z.literal(1),
  game: z.string().regex(GAME_ID_RE),
  target: z.object({ version: z.string().trim().min(1).max(32) }).strict(),
  /** The project's reserved namespace (nx_<hash>); every identifier the mod defines lives under it. */
  namespace: z.string().regex(NAMESPACE_RE, "namespace must be the project's reserved nx_<hash>"),
  summary: z.string().trim().min(10).max(2000),
  routes: z.array(z.enum(ARTIFACT_ROUTES)).min(1).max(ARTIFACT_ROUTES.length),
  requirements: z.array(RequirementZ).min(1).max(100),
  nonGoals: z.array(line(300)).max(50).default([]),
  constraints: z.array(line(300)).max(50).default([]),
  assets: z.array(AssetSlotZ).max(200).default([]),
  tests: z.array(TestPlanZ).max(100).default([]),
  install: InstallZ,
  config: ConfigSectionZ.optional(),
}).strict();

export type ModSpec = z.output<typeof ModSpecV1Schema>;
export type ModSpecInput = z.input<typeof ModSpecV1Schema>;
export type Requirement = ModSpec["requirements"][number];
export type AssetSlot = ModSpec["assets"][number];
export type TestPlan = ModSpec["tests"][number];

export type SpecIssue = { path: string; code: string; message: string };

/** JSON Schema (draft 2020-12) of what a producer writes (defaults optional). */
export function modSpecJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(ModSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// schemaVersion migrations
// ---------------------------------------------------------------------------

/** `SPEC_MIGRATIONS[n]` rewrites a version-n document into version n+1. Empty while v1 is the only version. */
export type SpecMigration = (doc: Record<string, unknown>) => Record<string, unknown>;
export const SPEC_MIGRATIONS: Readonly<Record<number, SpecMigration>> = {};

export type MigrateResult =
  | { ok: true; doc: Record<string, unknown>; from: number; applied: number[] }
  | { ok: false; errors: SpecIssue[] };

/** Bring a stored document up to CURRENT_SCHEMA_VERSION. Never guesses a missing version. */
export function migrateSpec(raw: unknown, migrations: Readonly<Record<number, SpecMigration>> = SPEC_MIGRATIONS, current: number = CURRENT_SCHEMA_VERSION): MigrateResult {
  const err = (code: string, message: string): MigrateResult => ({ ok: false, errors: [{ path: "schemaVersion", code, message }] });
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: [{ path: "", code: "not_object", message: "spec must be a JSON object" }] };
  const v = (raw as Record<string, unknown>).schemaVersion;
  if (v === undefined) return err("missing_schema_version", "spec has no schemaVersion");
  if (typeof v !== "number" || !Number.isInteger(v) || v < 0) return err("bad_schema_version", "schemaVersion must be a whole number");
  if (v > current) return err("schema_too_new", `spec schemaVersion ${v} is newer than this engine (${current})`);
  let doc = { ...(raw as Record<string, unknown>) };
  const applied: number[] = [];
  for (let n = v; n < current; n++) {
    const m = migrations[n];
    if (!m) return err("no_migration", `no migration from schemaVersion ${n} to ${n + 1}`);
    doc = { ...m(doc), schemaVersion: n + 1 };
    applied.push(n);
  }
  return { ok: true, doc, from: v, applied };
}

// ---------------------------------------------------------------------------
// validation
// ---------------------------------------------------------------------------

export type ValidateOptions = {
  /** Game adapter lookup (lib/cyrus/adapters getAdapter). Without it, game and version are not checked (`unchecked_game` warning). */
  adapterFor?: (game: string) => GameAdapter | null;
  migrations?: Readonly<Record<number, SpecMigration>>;
};

export type ValidateResult =
  | { ok: true; spec: ModSpec; warnings: SpecIssue[]; migratedFrom: number }
  | { ok: false; errors: SpecIssue[]; warnings: SpecIssue[] };

const pathOf = (p: readonly PropertyKey[]) => p.map((k) => (typeof k === "number" ? `[${k}]` : `.${String(k)}`)).join("").replace(/^\./, "");

/** Untrusted JSON -> ModSpec, or every problem found. */
export function validateModSpec(raw: unknown, opts: ValidateOptions = {}): ValidateResult {
  const mig = migrateSpec(raw, opts.migrations);
  if (!mig.ok) return { ok: false, errors: mig.errors, warnings: [] };
  const parsed = ModSpecV1Schema.safeParse(mig.doc);
  if (!parsed.success) {
    return { ok: false, warnings: [], errors: parsed.error.issues.map((i) => ({ path: pathOf(i.path), code: i.code, message: i.message })) };
  }
  const spec = parsed.data;
  const errors: SpecIssue[] = [];
  const warnings: SpecIssue[] = [];

  const dupes = (list: string[], path: string, what: string) => {
    const seen = new Set<string>();
    list.forEach((id, i) => {
      if (seen.has(id)) errors.push({ path: `${path}[${i}]`, code: "duplicate_id", message: `${what} ${id} is listed twice` });
      seen.add(id);
    });
  };
  dupes(spec.requirements.map((r) => r.id), "requirements", "requirement");
  dupes(spec.assets.map((a) => a.id), "assets", "asset");
  dupes(spec.tests.map((t) => t.id), "tests", "test");
  dupes(spec.routes, "routes", "route");

  const reqs = new Set(spec.requirements.map((r) => r.id));
  spec.assets.forEach((a, i) => {
    if (a.libraryRef && a.source !== "library") errors.push({ path: `assets[${i}].libraryRef`, code: "library_ref_needs_library_source", message: `asset ${a.id} has a libraryRef but its source is ${a.source}` });
    if (a.source === "library" && !a.libraryRef) warnings.push({ path: `assets[${i}]`, code: "library_ref_missing", message: `asset ${a.id} comes from the library but names no catalog asset (libraryRef)` });
  });
  spec.assets.forEach((a, i) => a.requirementIds.forEach((r, j) => {
    if (!reqs.has(r)) errors.push({ path: `assets[${i}].requirementIds[${j}]`, code: "unknown_requirement", message: `asset ${a.id} points at ${r}, which is not a requirement` });
  }));
  const covered = new Set<string>();
  spec.tests.forEach((t, i) => t.covers.forEach((r, j) => {
    if (!reqs.has(r)) errors.push({ path: `tests[${i}].covers[${j}]`, code: "unknown_requirement", message: `test ${t.id} covers ${r}, which is not a requirement` });
    covered.add(r);
  }));
  spec.requirements.forEach((r, i) => {
    if (r.priority === "must" && !covered.has(r.id)) warnings.push({ path: `requirements[${i}]`, code: "untested_requirement", message: `${r.id} is a must-have with no acceptance test` });
  });

  if (spec.config) {
    // the ConfigSpec cross-field rules (Zod checked the shape) + the stored values against the schema
    const raw = (mig.doc as { config?: { spec?: unknown } }).config?.spec;
    const c = validateConfigSpec(raw);
    if (!c.ok) for (const e of c.errors) errors.push({ path: `config.spec.${e.path}`, code: e.code, message: e.message });
    else {
      for (const w of c.warnings) warnings.push({ path: `config.spec.${w.path}`, code: w.code, message: w.message });
      if (spec.config.values) for (const e of checkValues(c.spec, spec.config.values, "strict").errors) errors.push({ path: `config.values.${e.key}`, code: e.code, message: e.message });
    }
  }

  if (!opts.adapterFor) {
    warnings.push({ path: "game", code: "unchecked_game", message: "game and target version were not checked against an adapter" });
  } else {
    const adapter = opts.adapterFor(spec.game);
    if (!adapter) {
      errors.push({ path: "game", code: "unknown_game", message: `no game adapter for "${spec.game}"` });
    } else {
      const v = adapter.versions.get(spec.target.version);
      if (!v) errors.push({ path: "target.version", code: "unknown_version", message: `${adapter.name} ${spec.target.version} is not in the version registry` });
      else if (v.status === "blocked") errors.push({ path: "target.version", code: "blocked_version", message: `${adapter.name} ${spec.target.version} is blocked` });
      else if (!v.buildable) warnings.push({ path: "target.version", code: "version_not_buildable", message: `${adapter.name} ${spec.target.version} is ${v.status}: Cyrus cannot build it yet` });
      spec.routes.forEach((r, i) => {
        const a = adapter.artifacts.find((x) => x.route === r);
        if (!a || a.availability === "unsupported") warnings.push({ path: `routes[${i}]`, code: "route_unsupported", message: `${adapter.name} cannot use the ${r} route` });
      });
      spec.assets.forEach((a, i) => {
        if (!adapter.assetDelivery[a.kind].supported) warnings.push({ path: `assets[${i}]`, code: "asset_kind_undeliverable", message: `${adapter.name} has no way to deliver ${a.kind} assets` });
      });
    }
  }
  return errors.length ? { ok: false, errors, warnings } : { ok: true, spec, warnings, migratedFrom: mig.from };
}
// Cyrus engine core: the minimal capability router (MASTER-PLAN 4.3). DETERMINISTIC: no AI call, no network.
// Given a ModSpec (and optionally the raw prompt) and the game's adapter, decide which artifact routes the mod
// needs, which of them Cyrus can build today, and the honest limits the user must see before tokens are spent.
// With a plan, the asset tier gate runs here first and DOWNGRADES (strips gated custom assets with a reason)
// instead of failing. Game-agnostic: all game facts are the adapter's route rules and version capabilities.
import type { GameAdapter, RouteRule } from "../adapters/types";
import { ARTIFACT_ROUTES, type ArtifactRoute, type ModSpec } from "./spec";
import { canAsset, downgradeSpecAssets, type AssetDenial } from "./asset-gate";

export type RouteLimit = { id: string; severity: "info" | "warn" | "block"; message: string };

export type RouteDecision = {
  game: string;
  version: string;
  /** Every route the mod needs, in canonical order. */
  routes: ArtifactRoute[];
  /** Subsets of `routes` by what the adapter can do today. */
  available: ArtifactRoute[];
  planned: ArtifactRoute[];
  unsupported: ArtifactRoute[];
  /** "plugin", "plugin+resourcePack", "dataPack", ... or "clientMod-unsupported" when nothing buildable is left. */
  label: string;
  /** True when every needed route is available today and nothing blocks the target version. */
  buildableNow: boolean;
  limits: RouteLimit[];
  matchedRules: string[];
  /** The spec after the plan downgrade (unchanged when no plan was given). */
  spec: ModSpec;
  removedAssets: AssetDenial[];
};

export type RouteOptions = {
  prompt?: string;
  /** Pass to apply the asset tier gate. `{ plan: undefined }` = unknown plan, so asset creation fails closed. */
  gate?: { plan: unknown };
  /** Planned routes the HOST has switched on here (e.g. dataPack behind CYRUS_DATAPACK_STUDIO): they count as available. */
  routesOn?: readonly ArtifactRoute[];
};

const order = (s: Set<ArtifactRoute>) => ARTIFACT_ROUTES.filter((r) => s.has(r));

/** The text routing reads. Non-goals and constraints are left out on purpose ("no custom blocks" must not trigger). */
function routingText(spec: ModSpec, prompt?: string): string {
  return [spec.summary, ...spec.requirements.map((r) => r.text), ...spec.assets.map((a) => a.purpose), prompt ?? ""].join("\n").toLowerCase();
}

const compiled = new WeakMap<RouteRule, RegExp[]>();
function keywordHit(rule: RouteRule, text: string): boolean {
  let res = compiled.get(rule);
  if (!res) { res = rule.keywords.map((k) => new RegExp(k, "i")); compiled.set(rule, res); }
  return res.some((re) => re.test(text));
}

export function routeSpec(input: ModSpec, adapter: GameAdapter, opts: RouteOptions = {}): RouteDecision {
  const limits: RouteLimit[] = [];
  const matchedRules: string[] = [];
  let spec = input;
  let removedAssets: AssetDenial[] = [];
  if (opts.gate) {
    const d = downgradeSpecAssets(input, opts.gate.plan);
    spec = d.spec;
    removedAssets = d.removed;
    d.removed.forEach((r, i) => limits.push({ id: `asset_gate:${r.assetId}`, severity: "warn", message: d.notices[i] }));
  }
  const version = spec.target.version;
  const text = routingText(spec, opts.prompt);
  const kinds = new Set(spec.assets.map((a) => a.kind));
  const need = new Set<ArtifactRoute>(spec.routes);

  for (const rule of adapter.routeRules) {
    const byAsset = !!rule.assetKinds?.some((k) => kinds.has(k));
    if (!byAsset && !keywordHit(rule, text)) continue;
    matchedRules.push(rule.id);
    // Asked for in words only, for asset kinds this plan may not create: say so, do not add the route.
    if (!byAsset && opts.gate && rule.assetKinds?.length && rule.assetKinds.every((k) => !canAsset(opts.gate!.plan, k, "create").ok)) {
      const d = canAsset(opts.gate.plan, rule.assetKinds[0], "create");
      if (!d.ok) limits.push({ id: `${rule.id}:plan`, severity: "warn", message: d.reason });
      continue;
    }
    if (rule.route) need.add(rule.route);
    if (rule.limit) limits.push({ id: rule.id, severity: rule.limit.severity, message: rule.limit.message });
    const fb = rule.requiresCapability?.fallback;
    if (rule.requiresCapability && !adapter.versions.hasCapability(version, rule.requiresCapability.capability) && fb && adapter.versions.hasCapability(version, fb.capability)) {
      limits.push({ id: `${rule.id}:version`, severity: "warn", message: fb.message.replaceAll("{version}", version) });
    } else if (rule.requiresCapability && !adapter.versions.hasCapability(version, rule.requiresCapability.capability)) {
      limits.push({ id: `${rule.id}:version`, severity: rule.requiresCapability.downgrade ? "warn" : "block", message: rule.requiresCapability.message.replaceAll("{version}", version) });
    }
  }

  const v = adapter.versions.get(version);
  if (!v) limits.push({ id: "version:unknown", severity: "block", message: `${adapter.name} ${version} is not in the version registry.` });
  else if (!v.buildable) limits.push({ id: "version:not_buildable", severity: "block", message: `${adapter.name} ${version} is ${v.status}: Cyrus cannot build for it yet.` });

  if (need.size === 0) need.add(adapter.defaultRoute);
  const routes = order(need);
  const avail = (r: ArtifactRoute) => {
    const a = adapter.artifacts.find((x) => x.route === r)?.availability ?? "unsupported";
    return a === "planned" && opts.routesOn?.includes(r) ? "available" : a;
  };
  const available = routes.filter((r) => avail(r) === "available");
  const planned = routes.filter((r) => avail(r) === "planned");
  const unsupported = routes.filter((r) => avail(r) === "unsupported");
  for (const r of [...planned, ...unsupported]) {
    const a = adapter.artifacts.find((x) => x.route === r);
    limits.push({ id: `route:${r}`, severity: "warn", message: a?.note ?? `${adapter.name} cannot use the ${r} route.` });
  }
  const live = routes.filter((r) => avail(r) !== "unsupported");
  const label = live.length ? live.join("+") : unsupported.includes("clientMod") ? "clientMod-unsupported" : "unsupported";
  const buildableNow = live.length > 0 && planned.length === 0 && unsupported.length === 0 && !limits.some((l) => l.severity === "block");
  return { game: adapter.game, version, routes, available, planned, unsupported, label, buildableNow, limits, matchedRules, spec, removedAssets };
}

// Asset profile: what ONE game's adapter declares about 3D/texture assets (MULTIGAME research H-3d-games.md, section 3).
// Interfaces + a validator only. Nothing here changes behaviour; Minecraft is the first filled-in profile, every
// other game declares its own when its adapter is written. Pure, client-safe, no Nxeon imports.
import type { AdapterMaturity } from "./types";
import type { MotionCapability } from "../motion/caps";

/** How custom assets reach players. Only the first and the two workshop forms need no player action. */
export const DELIVERY_STRATEGIES = ["server-streamed", "workshop-user-publishes", "workshop-platform-publishes", "client-manual", "none"] as const;
export type DeliveryStrategy = (typeof DELIVERY_STRATEGIES)[number];

/** Which kind of worker a job needs. linux-cpu = node-2 style builds; windows-tools = Windows-only game tools; gpu = image/3D models. */
export const WORKER_CLASSES = ["linux-cpu", "windows-tools", "gpu"] as const;
export type WorkerClass = (typeof WORKER_CLASSES)[number];

/** none = nothing from the game needed; user-supplied = the user brings templates/base files; platform-licensed = Nxeon holds a licence. */
export const REQUIRED_GAME_FILES = ["none", "user-supplied", "platform-licensed"] as const;
export type RequiredGameFiles = (typeof REQUIRED_GAME_FILES)[number];

/** Channel roles of a texture set. Stored as separate lossless layers; packed into engine channels only at export. */
export const CHANNEL_ROLES = ["albedo", "normal", "roughness", "metallic", "ao", "emissive", "height", "opacity", "mask"] as const;
export type ChannelRole = (typeof CHANNEL_ROLES)[number];

export type ColorSpace = "srgb" | "linear";
export type NormalConvention = "opengl" | "directx" | "none";
export type TextureCompression = "png" | "bc1" | "bc3" | "bc5" | "bc7" | "ktx2";
export type EngineFamily = "minecraft-java" | "unreal" | "unity" | "source" | "rage" | "creation" | "hytale" | "other";

/** Where a role lands in the game's packed texture: a file name pattern and the channel(s) of it. */
export type ChannelTarget = { file: string; channels: "rgb" | "rgba" | "r" | "g" | "b" | "a" };

/** What the game owner's published terms say about hosted modding. `reviewed` is false until a human read the page. */
export type LegalPolicy = {
  policyUrl: string | null;
  /** true / false only when a reviewer read the source; otherwise "unknown" (the honest default). */
  commercialOk: boolean | "unknown";
  aiOk: boolean | "unknown";
  /** A game's own assets are never redistributed, so this is the literal false. */
  redistributeBase: false;
  monetisationRule?: string;
  attestationRequired: boolean;
  /** ISO date the policy page was last read, or null. */
  retrievedAt: string | null;
  reviewed: boolean;
};

export type AssetProfile = {
  game: string;
  engineFamily: EngineFamily;
  meshFormats: readonly string[];
  textureFormats: readonly string[];
  compression: readonly TextureCompression[];
  channelMap: Readonly<Partial<Record<ChannelRole, ChannelTarget>>>;
  normalConvention: NormalConvention;
  colorSpace: Readonly<Partial<Record<ChannelRole, ColorSpace>>>;
  /** Largest texture edge in pixels the game/adapter accepts. */
  maxTextureRes: number;
  /** AI mesh (meshgen, Model Studio L4) targets. Absent = the game takes no meshgen meshes (Minecraft: no meshes). */
  meshBudget?: AssetMeshBudget;
  /** reuse-template = the user's UV layout is kept; new = Cyrus may unwrap; none = the game has no UVs to manage. */
  uvRules: "reuse-template" | "new" | "none";
  skeletonPolicy: "reuse" | "own" | "none" | "forbidden";
  packaging: string;
  delivery: DeliveryStrategy;
  workerClass: WorkerClass;
  requiredGameFiles: RequiredGameFiles;
  legal: LegalPolicy;
  validators: readonly string[];
  previewShader: string;
  maturity: AdapterMaturity;
  /** optional catalog hints (asset catalog v2); see CatalogFitHints */
  catalog?: CatalogFitHints;
  /** what the game's motion lowering supports (the motion core's adapter contract, lib/cyrus/motion). Absent = no motion yet. */
  motion?: MotionCapability;
};

/**
 * What the asset CATALOG needs to judge "does this library asset fit this game" (lib/cyrus/library/v2/fit.ts).
 * Optional: a game without hints gets no fit row (unknown), never an assumed "good".
 *   accepts: per catalog kind, native = used as is / convert = Cyrus has a working converter / none = cannot use it.
 */
export type CatalogFitHints = {
  accepts: Readonly<Partial<Record<"model" | "texture-set" | "texture" | "sprite" | "hdri" | "decal" | "sound" | "music" | "flipbook" | "particle-texture" | "animation-clip" | "animated-model" | "motion-preset" | "effect-preset", "native" | "convert" | "none">>>;
  /** why a kind is "none" (shown to the model and the owner) */
  noneReasons?: Readonly<Partial<Record<string, string>>>;
  /** styles that look at home in the game (pixel-art for Minecraft); other styles fit "ok" at best */
  styleAffinity: readonly string[];
  /** triangle budgets per use (a single prop, a character, a vehicle); absent = not a mesh game */
  triBudget?: Readonly<{ prop: number; character: number; vehicle: number }>;
  /** largest texture edge before a downscale is needed, and the smallest that still reads well */
  textureRes?: Readonly<{ max: number; ideal: readonly number[] }>;
  audio?: Readonly<{ format: string; channels: number; maxSeconds?: number; note?: string }>;
};

/** Mesh targets an adapter declares for meshgen output. Triangles are per asset; perCategory narrows them. */
export type AssetMeshBudget = {
  maxTriangles: number;
  maxMaterials: number;
  /** LOD triangle targets, highest first. meshgen does not build LODs yet (a non-empty list yields a warning). */
  lods: readonly number[];
  maxObjects?: number;
  maxGlbBytes?: number;
  /** Keyed by meshgen category ("weapon-ranged", "container", ...). */
  perCategory?: Readonly<Partial<Record<string, { maxTriangles?: number; maxExtentM?: number; minExtentM?: number }>>>;
};

export type ProfileIssue = { path: string; code: string; message: string };

/** Cheap structural rules a profile must satisfy; returns issues, never throws. */
export function validateAssetProfile(p: AssetProfile): ProfileIssue[] {
  const out: ProfileIssue[] = [];
  const add = (path: string, code: string, message: string) => out.push({ path, code, message });
  if (!DELIVERY_STRATEGIES.includes(p.delivery)) add("delivery", "bad_delivery", `unknown delivery strategy ${String(p.delivery)}`);
  if (!WORKER_CLASSES.includes(p.workerClass)) add("workerClass", "bad_worker_class", `unknown worker class ${String(p.workerClass)}`);
  if (!REQUIRED_GAME_FILES.includes(p.requiredGameFiles)) add("requiredGameFiles", "bad_required_files", `unknown value ${String(p.requiredGameFiles)}`);
  if ((p.legal.redistributeBase as unknown) !== false) add("legal.redistributeBase", "must_be_false", "a game's base assets are never redistributed");
  if ((p.legal.commercialOk === true || p.legal.aiOk === true) && !p.legal.reviewed) add("legal.reviewed", "unreviewed_claim", "commercialOk/aiOk can only be true after a human reviewed the policy");
  if (p.legal.reviewed && (!p.legal.policyUrl || !p.legal.retrievedAt)) add("legal.policyUrl", "missing_source", "a reviewed policy needs its url and retrieval date");
  if (p.maturity === "stable" && !p.legal.reviewed) add("maturity", "stable_needs_legal", "a stable adapter needs a reviewed legal policy");
  if (p.delivery === "client-manual" && p.maturity === "stable") add("delivery", "manual_not_stable", "assets players must install by hand cannot be a stable path");
  if (p.requiredGameFiles !== "none" && p.legal.attestationRequired !== true) add("legal.attestationRequired", "attestation_needed", "user-supplied or licensed game files need an ownership attestation");
  if (p.workerClass === "windows-tools" && p.requiredGameFiles === "platform-licensed") add("requiredGameFiles", "windows_licensed", "a Windows worker must not hold a platform-licensed game install without a separate legal review");
  if (!(p.maxTextureRes >= 16 && p.maxTextureRes <= 16384)) add("maxTextureRes", "bad_res", "maxTextureRes must be between 16 and 16384");
  if (p.channelMap.albedo && p.colorSpace.albedo && p.colorSpace.albedo !== "srgb") add("colorSpace.albedo", "albedo_srgb", "albedo is stored in sRGB");
  if (p.colorSpace.normal && p.colorSpace.normal !== "linear") add("colorSpace.normal", "normal_linear", "normal maps are linear data");
  if (p.channelMap.normal && p.normalConvention === "none") add("normalConvention", "normal_needs_convention", "a normal channel needs opengl or directx");
  if (p.meshBudget) {
    const b = p.meshBudget;
    if (!(Number.isInteger(b.maxTriangles) && b.maxTriangles >= 100)) add("meshBudget.maxTriangles", "bad_mesh_budget", "maxTriangles must be an integer >= 100");
    if (!(Number.isInteger(b.maxMaterials) && b.maxMaterials >= 1)) add("meshBudget.maxMaterials", "bad_mesh_budget", "maxMaterials must be an integer >= 1");
    if (b.lods.some((n, i) => n >= (i ? b.lods[i - 1] : b.maxTriangles))) add("meshBudget.lods", "bad_lods", "LOD targets must shrink, starting below maxTriangles");
    if (p.meshFormats.length === 0) add("meshBudget", "budget_without_format", "a mesh budget needs at least one mesh format");
  }
  if (p.motion) {
    const m = p.motion;
    if (m.game !== p.game) add("motion.game", "motion_game", `the motion capability is for ${m.game}, the profile for ${p.game}`);
    if (!(m.tickRate >= 1 && m.tickRate <= 240)) add("motion.tickRate", "motion_tick", "tickRate must be 1..240");
    if (m.attach && !m.nodeKinds.includes("seat") && !m.nodeKinds.includes("socket")) add("motion.attach", "motion_attach", "attach needs seat or socket nodes");
    if (m.trackKinds.material === "none" && m.materialChannels.length) add("motion.materialChannels", "motion_material", "material channels listed but material tracks are unsupported");
    for (const [k, v] of Object.entries(m.caps)) if (!(Number.isInteger(v) && v >= 0)) add(`motion.caps.${k}`, "motion_cap", `${k} must be a whole number >= 0`);
  }
  for (const role of Object.keys(p.channelMap)) if (!CHANNEL_ROLES.includes(role as ChannelRole)) add(`channelMap.${role}`, "bad_role", `unknown channel role ${role}`);
  return out;
}
