function ThemeButton() {
  const [light, setLight] = useState(false);
  useEffect(() => { setLight(document.documentElement.getAttribute("data-theme") === "light"); }, []);
  const flip = () => {
    const next = !light;
    if (next) document.documentElement.setAttribute("data-theme", "light"); else document.documentElement.removeAttribute("data-theme");
    try { localStorage.setItem("nx-theme", next ? "light" : "dark"); } catch { /* storage blocked: the switch still works for this page */ }
    setLight(next);
  };
  return (
    <button type="button" className="cys-chip cys-soft icon" onClick={flip} aria-label="Switch light or dark" title="Switch light or dark">
      <SI n={light ? "sun" : "moon"} />
    </button>
  );
}

/**
 * `showModel`: the Model link in the studio switch (only when the server says Model Studio is visible to this viewer).
 * `seg` / `icon` / `kind`: the designer studios replace the Texture/Sound switch with their own (Items / Menus / Quests /
 * Bosses) and name their crumb icon; `kind` is the data-studio attribute.
 */
export function StudioShell({ mod, current, studio, children, showModel = false, showConfig = false, seg, icon, kind, trail }: { mod: StudioMod | null; /** r31: account-level pages (Mod Packs, Import): crumbs after Minecraft, no mod */ trail?: { label: string; href?: string }[]; current: string; studio: StudioKindUI | null; children: ReactNode; showModel?: boolean; /** the Config link (only when the server says the Config Studio is on for this viewer) */ showConfig?: boolean; seg?: ReactNode; icon?: ReactNode; kind?: string }) {
  const [toast, setToast] = useState<Toast>(null);
  const show = useCallback((msg: string, err?: boolean) => setToast({ msg, err, id: Date.now() }), []);
  useEffect(() => { if (!toast) return; const t = window.setTimeout(() => setToast(null), 3200); return () => window.clearTimeout(t); }, [toast]);
  const head: ReactNode[] = [
    <Link key="core" className="cys-crumb" href="/dashboard/cyrus"><span className="core" />Core</Link>,
    // eslint-disable-next-line @next/next/no-img-element
    <Link key="g" className="cys-crumb" href="/dashboard/cyrus"><img src="/cyrus/games/minecraft.svg" alt="" width={15} height={15} />Minecraft</Link>,
  ];
  const c = mod?.category ?? { key: "misc", label: "", rgb: "150 120 255" };
  const crumbs: ReactNode[] = !mod ? [...head, ...(trail ?? []).map((t, i) => (t.href ? <Link key={`t${i}`} className="cys-crumb" href={t.href}>{t.label}</Link> : <span key={`t${i}`} className="cys-crumb">{t.label}</span>)), <span key="s" className="cys-crumb on" aria-current="page">{icon}{current}</span>] : [
    ...head,
    <Link key="c" className="cys-crumb" href="/dashboard/cyrus"><span style={{ color: `rgb(${c.rgb})`, display: "flex", fontSize: 14 }}><CategoryIcon k={c.key} /></span>{c.label}</Link>,
    <Link key="m" className="cys-crumb" href={assetsHref(mod!)}><span className="cys-dot" style={{ background: `rgb(${c.rgb})`, boxShadow: `0 0 8px rgb(${c.rgb})` }} /><span style={{ maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis" }}>{mod.name}</span></Link>,
    <span key="s" className="cys-crumb on" aria-current="page">{icon ?? <SI n={studio === "sound" ? "wave" : studio === "model" ? "cube" : studio === "config" ? "gauge" : "image"} />}{current}</span>,
  ];
  return (
    <ToastCtx.Provider value={show}>
      <div className="cys" data-studio={kind ?? studio ?? "plans"}>
        <header className="cys-top">
          <Link href="/dashboard/cyrus" className="cys-brand" aria-label="Cyrus home">
            <CyrusWordmark height={19} className="topbar-logo" />
            <small>Mod Forge</small>
          </Link>
          <nav className="cys-crumbs cys-soft" aria-label="Location">
            {crumbs.map((x, i) => <Fragment key={i}>{i > 0 && <SI n="chevR" />}{x}</Fragment>)}
          </nav>
          <div className="cys-tbr">
            {seg}
            {!seg && studio && mod && (
              <div className="cys-seg cys-soft hide-n" aria-label="Studio">
                <Link href={studioHref(mod, "texture")} className={studio === "texture" ? "on" : ""} aria-current={studio === "texture" ? "page" : undefined}><SI n="image" />Texture</Link>
                <Link href={studioHref(mod, "sound")} className={studio === "sound" ? "on" : ""} aria-current={studio === "sound" ? "page" : undefined}><SI n="wave" />Sound</Link>
                {(showModel || studio === "model") && <Link href={studioHref(mod, "model")} className={studio === "model" ? "on" : ""} aria-current={studio === "model" ? "page" : undefined}><SI n="cube" />Model</Link>}
                {(showConfig || studio === "config") && <Link href={studioHref(mod, "config")} className={studio === "config" ? "on" : ""} aria-current={studio === "config" ? "page" : undefined}><SI n="gauge" />Config</Link>}
              </div>
            )}
            {mod && <Link className="cys-chip cys-soft hide-n" href={assetsHref(mod)}><SI n="package" />Mod assets</Link>}
            <span className="hide-n"><CyrusTokenChip compact beta={false} /></span>
            <ThemeButton />
          </div>
        </header>
        {children}
        {toast && (
          <div key={toast.id} className={`cys-toast ${toast.err ? "err" : ""}`} role="status">
            <SI n={toast.err ? "warn" : "check"} /><span>{toast.msg}</span>
          </div>
        )}
      </div>
    </ToastCtx.Provider>
  );
}

// Cyrus R3 gameplay designers: the DESIGN IR. A typed Custom Item Designer spec (ItemDesign) with an ability/event
// graph (AbilityGraph = trigger -> conditions -> actions, with branches) that the compiler (./compile.ts) turns into
// straight Java calling the verified component library (./components). Nothing here is free-form code: every node is a
// fixed kind, every number has a hard min/max (CAPS below; the JSON Schema carries them too), every activation has a
// static worst-case resource budget that must fit BUDGET, loops are bounded (query_* `max`, delayed `delayTicks` and
// nesting depth) and there is no way to run a command or arbitrary code. Numbers, texts and sound keys become config.yml
// parameters (editable without regenerating the mod, see ./params.ts); structure (kinds, effects, particles, targets)
// is code.
//
// Files: the build model writes one ItemDesign per file at assets/designs/<id>.json; a mod has at most
// DESIGN_LIMITS.maxItems of them. Identifiers live in the project's reserved namespace (engine-core identifiers):
// an item's full id is `nx_<8>:<id>`. Validation never throws: { ok, design | errors, warnings, checks, budgets }.
// The JSON Schema (designer.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-designer-artifacts.ts;
// a test fails while it is stale).
import { z } from "zod";
import { NAMESPACE_RE, buildIdentifier } from "../engine-core/identifiers";
import { IngredientSchema, TEXT_COLORS, canonicalJson } from "../datapack/spec";
import { compareMc, isVanilla, missingIdReason, vanillaIds } from "../datapack/versions";
import { getVersion } from "../versions/registry";

export const DESIGN_SPEC_VERSION = 1;
export { canonicalJson };

/** Per-mod limits. */
export const DESIGN_LIMITS = { maxItems: 6, maxSpecBytes: 64 * 1024, maxAbilities: 6, maxNodes: 48, maxDepth: 3, maxConditions: 8, maxActions: 16, maxMarks: 4, maxPassives: 4, maxLore: 6, maxPermissions: 8 } as const;

/**
 * Hard caps on every number (inclusive). The config loader clamps to the SAME caps at runtime, so a hand-edited
 * config.yml can never exceed them. Ticks: 20 = 1 second.
 */
export const CAPS = {
  cooldownTicks: [0, 72000], // up to 1 hour
  chargesMax: [1, 20],
  chargeRegenTicks: [20, 72000],
  targetRange: [1, 32], // blocks the click triggers look for a target / point
  periodTicks: [10, 1200], // held_interval: never faster than twice a second
  minChargeTicks: [5, 200],
  maxChargeTicks: [10, 400],
  damage: [0, 40], // health points (2 = one heart)
  heal: [0, 20],
  potionTicks: [1, 1200], // up to 60 s
  amplifier: [0, 4], // level I..V
  strength: [0, 3], // knockback / pull / push horizontal velocity (blocks per tick)
  vertical: [0, 1.5],
  teleportRange: [1, 16],
  projectileSpeed: [0.2, 3],
  projectileLifetime: [20, 200],
  particleCount: [1, 64],
  particleSpread: [0, 4],
  particleSpeed: [0, 1],
  volume: [0, 2],
  pitch: [0.5, 2],
  giveCount: [1, 64],
  chargeCost: [1, 5],
  markTicks: [20, 1200],
  marksPerOwner: [1, 32],
  queryMarkedRadius: [1, 32],
  queryNearbyRadius: [1, 12],
  queryMax: [1, 16],
  delayTicks: [1, 100],
  chance: [0, 1],
  healthFraction: [0, 1],
  timeOfDay: [0, 23999],
  titleFadeTicks: [0, 40],
  titleStayTicks: [10, 200],
  passiveAmplifier: [0, 2],
  lootChance: [0, 1],
  statDamage: [1, 40], // shown attack damage (player base 1 + modifier)
  statAttackSpeed: [0.25, 4], // attacks per second
  durability: [1, 10000],
} as const satisfies Record<string, readonly [number, number]>;
export type CapName = keyof typeof CAPS;

/** Per-activation budget (static worst case must fit; the runtime Budget component enforces the same numbers). */
export const BUDGET = { actions: 64, entities: 32, tasks: 8, particles: 512, projectiles: 3 } as const;
/** Plugin-wide runtime caps (component constants). */
export const RUNTIME_CAPS = { liveTasks: 128, marksTotal: 2048, textChars: 120, titleChars: 40, subtitleChars: 60 } as const;

const capNum = (c: CapName) => z.number().min(CAPS[c][0]).max(CAPS[c][1]);
const capInt = (c: CapName) => z.number().int().min(CAPS[c][0]).max(CAPS[c][1]);

export const KEY = /^[a-z][a-z0-9_]{1,31}$/;
export const Key = z.string().regex(KEY, "2-32 chars: lowercase letters, digits, _; starts with a letter");
export const VanillaRef = z.string().max(80).regex(/^minecraft:[a-z0-9_./]+$/, "a vanilla id like minecraft:diamond");
export const NsRef = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id like nx_abcd1234:void_reaper");
export const SoundKey = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/, "a namespaced sound key like nx_abcd1234:void_reaper.pull or minecraft:entity.enderman.teleport");
export const COLORS = TEXT_COLORS;
export const Color = z.union([z.enum(TEXT_COLORS), z.string().regex(/^#[0-9a-fA-F]{6}$/)]);
export const Text = (max: number) => z.string().min(1).max(max).regex(/^[^\u0000-\u001f§]*$/, "plain text (no control characters or § codes)");
export const StyledText = z.strictObject({ text: Text(60), color: Color.optional() });

