  z.strictObject({ type: z.literal("projectile_hit"), tag: Key }),
  /** Every periodTicks while the item is held (main hand) or carried (inventory). */
  z.strictObject({ type: z.literal("held_interval"), periodTicks: capInt("periodTicks"), slot: z.enum(["main_hand", "inventory"]).optional() }),
  /** On join / on death while the item is in the inventory. */

