// Cyrus R3 gameplay designers: does a BUILD get the designer route? Pure + deterministic (no AI call; server side).
// Item-with-abilities requests (a weapon/staff/tonic/... plus an ability word: cooldown, right-click, charge, mark,
// pull, projectile, buff...) are built from a typed ItemDesign instead of free-form Java; menu / quest requests (a shop,
// a GUI, a dialogue, quests, missions, daily tasks; not auctions, player trading, banks, claims or minigames) are built
// from typed MenuDesign / QuestDesign files (./gameplay). OFF unless CYRUS_DESIGNER=1
// (fail closed): off, nothing is decided, nothing is recorded and the build request stays byte-identical. Designers are
// NOT plan-gated (owner decision); any texture / sound / model the design references still goes through the asset gates
// (the texture and sound routes decide those, not this one).
import { designFeatures } from "./spec";

export const DESIGNER_FLAG = "CYRUS_DESIGNER";
export const designerOn = (env: Record<string, string | undefined> = process.env) => env[DESIGNER_FLAG] === "1";

/** The thing the request is about (an item). */
export const ITEM_WORDS = /\b(swords?|blades?|katanas?|staffs?|staves|wands?|scythes?|daggers?|axes?|hammers?|maces?|spears?|halberds?|weapons?|relics?|amulets?|talismans?|tonics?|potions?|elixirs?|rods?|orbs?|gauntlets?|tridents?|bows?|crossbows?|shields?|charms?|custom items?|magic items?|artifacts?|gun|rifle|pistol|launcher)\b/i;
/** What it does (an ability the graph can express). */
export const ABILITY_WORDS = /\b(abilit(?:y|ies)|cooldowns?|right[- ]?clicks?|left[- ]?clicks?|sneak(?:ing)?|shift[- ]?(?:right[- ]?)?click|charges?|charged|charging|marks?|marked|pulls?|pulled|dash(?:es)?|blinks?|teleports?|launch(?:es)?|shoots?|fires?|projectiles?|bolts?|buffs?|heals?|healing|on hit|on kill|when (?:you )?(?:hit|kill|eat|drink|join|die)|passive|knockback|lifesteal|special attack|slows?|stuns?)\b/i;

/** R3 menus: an inventory GUI the menu designer can build (shops, selectors, kit menus, dialogues). */
export const MENU_WORDS = /\b(gui|guis|menus?|inventory (?:menu|gui|screen)|chest (?:menu|gui)|shops?|shop keepers?|shopkeepers?|selectors?|kit menu|warp menu|npc dialogues?|dialogues?|dialogs?)\b/i;
/** R3 quests: quest chains, objectives, daily tasks. */
export const QUEST_WORDS = /\b(quest ?chains?|quest givers?|quest objectives?|questlines?|quests?|missions?|daily (?:tasks?|challenges?|quests?)|weekly (?:tasks?|challenges?|quests?)|bounty|bounties)\b/i;
/** Motion props (the motion core's Minecraft lowering): doors, hatches, animated props, turrets, gun stands. */
export const MOTION_WORDS = /\b(doors?|gates?|hatch(?:es)?|trap ?doors?|drawbridges?|hinges?|hinged|lids?|animated (?:props?|blocks?|doors?|objects?|decorations?)|moving (?:props?|blocks?|parts?)|swinging|turrets?|gun (?:racks?|stands?|displays?)|weapon (?:racks?|stands?|displays?)|display entit(?:y|ies)|animation(?:s)?)\b/i;
/** Motion requests the props cannot express honestly (vehicles, rideables, entity / mob animation): no motion part. */
export const MOTION_EXCLUDE = /\b(cars?|vehicles?|trucks?|bikes?|motorcycles?|boats? you can drive|drivable|driveable|rideable|mounts?|steer(?:ing)?|planes?|helicopters?)\b/i;

/** Requests the menu/quest IR cannot express honestly (player-to-player trading, auctions, banks, claims, minigames): no gameplay route. */
export const GAMEPLAY_EXCLUDE = /\b(auction(?: house)?s?|player[- ]to[- ]player|trade with (?:other )?players|player shops?|chest shops?|sign shops?|bank(?:s|ing)?|loans?|land claims?|claims?|minigames?|bed ?wars|sky ?wars|parkour|leaderboards?|databases?|mysql|web ?hooks?|discord)\b/i;

/** R3 bosses: a boss fight or a wave encounter the boss designer can build ("boss bar" alone is a HUD request, not a boss). */
export const BOSS_WORDS = /\b(boss ?fights?|mini-?boss(?:es)?|raid boss(?:es)?|world boss(?:es)?|bosse?s?|encounters?|waves? of (?:mobs|monsters|enemies|zombies|skeletons)|wave (?:defen[cs]e|survival|fights?)|arena (?:fights?|battles?|waves?)|hordes?)\b/i;
/** Requests the boss IR cannot express honestly (custom models / animations need the creature pipeline; dungeons need worldgen; PvP arenas and minigames are not encounters). */
export const BOSS_EXCLUDE = /\b(dragon fight|ender ?dragon|wither (?:boss|fight)|custom (?:boss )?models?|animated boss(?:es)?|dungeons?|pvp arenas?|minigames?|bed ?wars|sky ?wars|leaderboards?|mythicmobs|mythic mobs)\b/i;

/** R4 glyph HUDs: text HUDs a server can show with a resource pack font (action bar, boss bar, sidebar). */
export const HUD_WORDS = /\b(huds?|heads?-up displays?|(?:mana|stamina|energy|ammo|rage|thirst) (?:bars?|meters?|display|counters?)|custom (?:health|mana|xp|energy|stamina|ammo) (?:bars?|display)|ammo counters?|cooldown (?:display|indicators?|bars?)|action ?bar (?:hud|display|text|icons?)|glyphs?|custom icons in (?:chat|the action ?bar)|scoreboard (?:hud|sidebar)|sidebar (?:hud|display|stats)|boss ?bar (?:hud|display|text|title))\b/i;
/** HUD requests a server cannot honestly build (they need a client mod or core shaders). */
export const HUD_EXCLUDE = /\b(mini-?maps?|waypoints? on (?:the )?screen|core shaders?|shaders?|free-?form (?:hud|widgets?)|anywhere on (?:the )?screen|draggable|custom gui textures?|keybinds?|client[- ]side mods?)\b/i;
export const HUD_LIMIT_NOTICE = "Free-form HUD widgets (minimaps, things placed anywhere on the screen, shaders) need a client mod. A server can show glyph HUDs in the action bar, boss bars and the sidebar, which is what Cyrus builds.";

/** HUD words (and no client-only feature). */
export function matchHudWords(text: string): { hud: boolean; excluded: boolean; matched: string[] } {
  const m = HUD_WORDS.exec(text ?? "");
  if (!m) return { hud: false, excluded: false, matched: [] };
  if (HUD_EXCLUDE.test(text ?? "")) return { hud: false, excluded: true, matched: [] };
  return { hud: true, excluded: false, matched: [`hud:${m[0].toLowerCase().slice(0, 30)}`] };
}

export type DesignerRouteInput = { text: string; explicit?: unknown; existing?: boolean; /** R3: the base build already ships menu / quest designs (keeps the MENUS AND QUESTS prompt part on change builds). */ existingGameplay?: boolean; /** R3: the base build ships boss / encounter designs (keeps the BOSSES AND ENCOUNTERS part). */ existingBosses?: boolean; /** R4: the base build ships HUD designs (keeps the HUD part). */ existingHud?: boolean; /** motion core: the base build ships motion designs (keeps the MOTION PROPS part on change builds). */ existingMotion?: boolean; mcVersion: string; on: boolean };
export type DesignerRouteDecision = { route: boolean; matched: string[]; notices: string[]; limits: string[]; /** R3: menu / quest words matched (present only then): the prompt gets the MENUS AND QUESTS part. */ gameplay?: { menus: boolean; quests: boolean }; /** R3: boss / encounter words matched (present only then): the BOSSES AND ENCOUNTERS part. */ bosses?: true; /** R4: HUD words matched (present only then): the HUD AND GLYPHS part. */ hud?: true; /** motion core: motion-prop words matched (present only then): the prompt gets the MOTION PROPS part. */ motion?: true };

/** Boss / encounter words (and no excluded feature): the boss part of the designer route. */
export function matchBossWords(text: string): string[] {
  const t = (text ?? "").replace(/\bboss ?bars?\b/gi, " ");
  if (BOSS_EXCLUDE.test(text ?? "")) return [];
  const m = BOSS_WORDS.exec(t);
  return m ? [`boss:${m[0].toLowerCase().slice(0, 30)}`] : [];
}

