  const ids = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : ""));
  inputs.forEach((_, i) => res.files.push({ id: ids[i] || `#${i}`, kind: kinds[i], ok: true, errors: [], warnings: [] }));
  if (inputs.length > GAMEPLAY_LIMITS.maxDesignFiles) fail(undefined, "(mod)", "too_many_files", `${inputs.length} design files; the limit is ${GAMEPLAY_LIMITS.maxDesignFiles}`);
  kinds.forEach((k, i) => { if (!k) fail(res.files[i].id, "kind", "unknown_kind", `"kind" must be absent/"item", "menu", "quest", "boss", "encounter", "hud" or "motion"`); });
  const dup = ids.find((k, i) => k && ids.indexOf(k) !== i);
  if (dup) fail(dup, "(mod)", "duplicate_item", `design ${dup} is defined twice (items, menus and quests share one id space)`);
  const count = (k: DesignKind) => kinds.filter((x) => x === k).length;
  if (count("menu") > GAMEPLAY_LIMITS.maxMenus) fail(undefined, "(mod)", "too_many_menus", `${count("menu")} menus; the limit is ${GAMEPLAY_LIMITS.maxMenus}`);
  if (count("quest") > GAMEPLAY_LIMITS.maxQuests) fail(undefined, "(mod)", "too_many_quests", `${count("quest")} quests; the limit is ${GAMEPLAY_LIMITS.maxQuests}`);
  if (count("boss") > BOSS_LIMITS.maxBosses) fail(undefined, "(mod)", "too_many_bosses", `${count("boss")} bosses; the limit is ${BOSS_LIMITS.maxBosses}`);
