// New-mod flow (r39): game -> version -> server, cost first (tokens the build may hold, from the account's own
// reserve table; never a price we made up), templates gallery, then the prompt. Creating posts to the same build API
// the studio uses (it re-checks plan, model and tokens server side) and lands on the new project's page.
import { useMemo, useState } from "react";
