export async function catalogSearch(input: { query?: unknown; kind?: unknown; game?: unknown; minQuality?: unknown; limit?: unknown }, ctx: ToolContext): Promise<ToolResult> {
  const query = typeof input.query === "string" ? input.query.trim().slice(0, 120) : "";
  if (query.length < 2) return out(false, { error: "query must be 2-120 characters" });
  const a = access(ctx.plan, ctx.proprietaryCleared);
  if (!a.plan) return out(false, { error: "plan_unknown: assets cannot be picked right now" });
  let kinds = a.kinds;
  if (input.kind != null) {
    if (!(CATALOG_KINDS as readonly unknown[]).includes(input.kind)) return out(false, { error: `unknown kind; use one of ${CATALOG_KINDS.join(", ")}` });
    const k = input.kind as CatalogKind;
    if (!kinds.includes(k)) { const d = canAsset(a.plan, gateKindOf(k), "create"); return out(false, { error: "asset_locked", needs: d.ok ? null : d.needs ?? null }); }
    kinds = [k];
  }
  if (!kinds.length || !a.tiers.length) return out(false, { error: "asset_locked: this plan cannot use library assets" });
  const game = typeof input.game === "string" && /^[a-z][a-z0-9-]{1,31}$/.test(input.game) ? input.game : ctx.game;
  const minQuality = Number.isInteger(input.minQuality) ? Math.max(0, Math.min(100, input.minQuality as number)) : 40;
  const limit = Number.isInteger(input.limit) ? Math.max(1, Math.min(SEARCH_LIMIT_MAX, input.limit as number)) : 6;
  const r = await ctx.index.search({ text: query, kinds, game, minQuality, tiers: a.tiers, limit: limit * 2, statuses: ["published"] });
  // one row per (kind, title): identical-looking assets (same name in two packs, HDRI resolutions) count as variants
  const rows: Record<string, unknown>[] = [];
  const seenTitle = new Map<string, Record<string, unknown>>();
  for (const h of r.hits) {
    const k = `${h.entry.kind}|${h.entry.title.toLowerCase()}`;
    const prev = seenTitle.get(k);
    if (prev) { prev.variants = (Number(prev.variants) || 1) + h.groupSize; continue; }
    const row = await compactRow(h.entry, game, ctx.index, h.groupSize);
    seenTitle.set(k, row); rows.push(row);
  }
  // hard budget: drop descriptions, then rows, until the result fits
  let body: Record<string, unknown> = { n: r.total, game, rows: rows.slice(0, limit) };
  if (JSON.stringify(body).length > RESULT_CHAR_BUDGET) body = { ...body, rows: rows.slice(0, limit).map(({ d: _d, ...x }) => x) };
  while (JSON.stringify(body).length > RESULT_CHAR_BUDGET && (body.rows as unknown[]).length > 1) body = { ...body, rows: (body.rows as unknown[]).slice(0, -1) };
  if (!rows.length) body.hint = "no match: try other words for the situation, another kind, or a lower minQuality";
  return out(true, body);
}

