input.content:
// Cyrus capability manifest (v8 structure, part 1): what ONE game + version can really use, so every picker shows only
// that. DERIVED, never hand-listed per game: the game adapter (routes, asset delivery, asset profile incl. catalog
// `accepts`, mesh budget, motion, designer kinds), the version registry capabilities, the designer feature check, the
// config exporters, GameSupport (example prompts) and the plan gate. Pure, no Nxeon imports. Design:
// /root/agent-notes/cyrus-designs/v8-structure/STRUCTURE-PLAN.md section 1.
//
// Three states: usable (shown) / locked (the PLAN blocks it: shown with the lock, existing behaviour) / hidden (the game
// or version cannot use it, or the host switch is off). A game/version reason becomes one `whyNot` help line; a
// switched-off feature gets none (a flag never leaks). An unknown game gets an empty manifest (fail closed).
import { getAdapter } from "../adapters";
import type { GameAdapter } from "../adapters/types";
import { canAsset, PLAN_LABEL, type AssetPlan } from "../engine-core/asset-gate";
import { ARTIFACT_ROUTES, ASSET_KINDS, type ArtifactRoute, type AssetKind } from "../engine-core/spec";
import { CATALOG_KINDS, type CatalogKind } from "../library/v2/entry";
import { exporterFor } from "../config/exporters";
import { designFeatures, PROJECTILES, TRIGGER_TYPES, CONDITION_TYPES } from "../designer/spec";
import { ACTION_TEMPLATES } from "../designer/studio/edit";
import { vanillaIds } from "../datapack/versions";
import { CYRUS_TEMPLATES, type CyrusTemplate } from "../templates";
import type { GameSupport } from "../games/support";
import minecraftSupport from "../games/minecraft";
import terrariaSupport from "../games/terraria";
import valheimSupport from "../games/valheim";
import zomboidSupport from "../games/zomboid";

export type Avail = "usable" | "locked" | "hidden";
/** Why something is hidden: the game cannot, this version cannot, or the host switched it off (never shown). */
export type HiddenBy = "game" | "version" | "switch";

/** Studio ids = the studio routes (/dashboard/cyrus/<id>/studio/<studio>) + "code" (describe it / files, always there). */
export const STUDIO_IDS = ["code", "items", "menus", "bosses", "motion", "datapacks", "texture", "sound", "model", "model-editor", "mesh", "config", "library"] as const;
export type StudioId = (typeof STUDIO_IDS)[number];
export const STUDIO_LABEL: Record<StudioId, string> = {
  code: "Describe it", items: "Items", menus: "Menus and quests", bosses: "Bosses", motion: "Motion", datapacks: "Data packs", texture: "Texture",
  sound: "Sound", model: "Model", "model-editor": "Model editor", mesh: "Mesh", config: "Config", library: "Library",
};
/** Designer kinds (design files) a game adapter can compile. */
export const DESIGNER_KINDS = ["item", "menu", "quest", "boss", "encounter", "hud", "motion"] as const;
export type DesignerKind = (typeof DESIGNER_KINDS)[number];
/** Part (module) kinds of a mod (ModSpec v2 modules, lib/cyrus/engine-core/modules.ts). */
export const PART_KINDS = ["items", "creatures", "quests", "menus", "bosses", "hud", "textures", "sounds", "models", "motions", "config", "datapack", "worldgen", "code"] as const;
export type PartKind = (typeof PART_KINDS)[number];

export type Entry<T extends string> = { id: T; state: Avail; reason?: string; by?: HiddenBy | "plan"; needs?: AssetPlan };
export type WhyNot = { id: string; title: string; reason: string; by: "game" | "version" };
export type Palette = { triggers: string[]; actions: string[]; conditions: string[]; projectiles: string[]; itemStates: boolean; animatedCreatures: boolean };

export type CapabilityManifest = {
  game: string;
  version: string;
  known: boolean;
  /** "code-only" = no adapter yet: Cyrus writes code, no studios, no assets. */
  level: "full" | "code-only" | "unknown";
  routes: Entry<ArtifactRoute>[];
  assetKinds: Entry<AssetKind>[];
  studios: Entry<StudioId>[];
  designers: Entry<DesignerKind>[];
  palette: Palette | null;
  libraryKinds: Entry<CatalogKind>[];
  partKinds: PartKind[];
  templates: CyrusTemplate[];
  examplePrompts: string[];
  whyNot: WhyNot[];
};

export type ManifestContext = {
  /** Pass to apply the plan gate (create/edit). `{ plan: null }` = unknown plan: gated studios fail closed (locked). */
  plan?: unknown;
  /** Host switches per studio (false = hidden with no help line). Absent = on. */
  switches?: Partial<Record<StudioId, boolean>>;
};

const SUPPORT: Readonly<Record<string, GameSupport>> = { minecraft: minecraftSupport, terraria: terrariaSupport, valheim: valheimSupport, zomboid: zomboidSupport };

/** Client-mod route rules (the adapter's own) shown as "why not" lines. Labels only; the reason is the adapter's text. */
const RULE_TITLE: Record<string, string> = { custom_block: "New block types", freeform_hud: "Minimaps and free-form HUD widgets", keybind: "Custom keybinds", custom_sky: "Custom skies and shaders" };
const human = (id: string) => id.replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());

function emptyManifest(game: string, version: string, known: boolean): CapabilityManifest {
  return { game, version, known, level: known ? "code-only" : "unknown", routes: [], assetKinds: [], studios: [], designers: [], palette: null, libraryKinds: [], partKinds: [], templates: [], examplePrompts: [], whyNot: [] };
}

/** The manifest for a code-only game (GameSupport, no adapter): describe it + files, nothing else. */
function codeOnly(game: string, version: string, s: GameSupport): CapabilityManifest {
  const m = emptyManifest(game, version, true);
  const hide = (id: StudioId): Entry<StudioId> => ({ id, state: "hidden", by: "game", reason: `Cyrus builds ${s.name} mods as code today` });
  m.studios = STUDIO_IDS.map((id) => (id === "code" ? { id, state: "usable" } : hide(id)));
  m.designers = DESIGNER_KINDS.map((id) => ({ id, state: "hidden", by: "game", reason: `the designers build Minecraft plugins; ${s.name} mods are written as code` }));
  m.libraryKinds = CATALOG_KINDS.map((id) => ({ id, state: "hidden", by: "game", reason: `no asset delivery for ${s.name} yet` }));
  m.partKinds = ["code"];
  m.examplePrompts = [...s.examplePrompts];
  m.templates = CYRUS_TEMPLATES.filter((t) => t.games.includes(game));
  m.whyNot = [
    { id: "asset-studios", title: "Texture, Sound, Model and Motion studios", reason: `Cyrus has no way to deliver art or audio to ${s.name} players yet (code-only today).`, by: "game" },
    { id: "designers", title: "Item, Menu, Boss and HUD designers", reason: `They build Minecraft plugins; ${s.name} mods are written as code.`, by: "game" },
    ...(exporterFor(game)?.maturity !== "verified" && exporterFor(game)?.maturity !== "preview" ? [{ id: "config", title: "Config studio", reason: `The ${s.name} settings exporter is planned, not built.`, by: "game" as const }] : []),
  ];
  return m;
}

/** What `game` at `version` can use. */
export function usableFor(game: string, version: string, ctx: ManifestContext = {}): CapabilityManifest {
  const adapter = getAdapter(game);
  if (!adapter) {
    const s = SUPPORT[game];
    return s ? codeOnly(game, version, s) : emptyManifest(game, version, false);
  }
  return fromAdapter(adapter, version, ctx);
}

function fromAdapter(a: GameAdapter, version: string, ctx: ManifestContext): CapabilityManifest {
  const m = emptyManifest(a.game, version, true);
  m.level = "full";
  const profile = a.assetProfile;
  const accepts = profile?.catalog?.accepts ?? {};
  const v = a.versions.get(version);
  const cap = (c: string) => !!v && a.versions.hasCapability(version, c);
  const planGiven = "plan" in ctx;
  const gate = (kind: AssetKind): Pick<Entry<string>, "state" | "by" | "needs" | "reason"> => {
    if (!planGiven) return { state: "usable" };
    const d = canAsset(ctx.plan, kind, "edit");
    return d.ok ? { state: "usable" } : { state: "locked", by: "plan", ...(d.needs ? { needs: d.needs } : {}), reason: d.needs ? `needs ${PLAN_LABEL[d.needs]}` : d.reason };
  };
  const whyNot: WhyNot[] = [];
  const seenWhy = new Set<string>();
  const addWhy = (w: WhyNot) => { if (!seenWhy.has(w.id)) { seenWhy.add(w.id); whyNot.push(w); } };

  // routes + asset kinds
  m.routes = ARTIFACT_ROUTES.map((r) => {
    const art = a.artifacts.find((x) => x.route === r);
    return !art || art.availability === "unsupported" ? { id: r, state: "hidden", by: "game", reason: art?.note ?? `${a.name} cannot use ${r}` } : { id: r, state: "usable" };
  });
  m.assetKinds = ASSET_KINDS.map((k) => (a.assetDelivery[k].supported ? { id: k, ...gate(k) } : { id: k, state: "hidden", by: "game", reason: a.assetDelivery[k].note }));
  const kindOk = (k: AssetKind) => a.assetDelivery[k].supported;

  // designers + palette (the designer compiler's own version check)
  const dk = new Set(a.designers ?? []);
  const fe = dk.size ? designFeatures(version) : null;
  m.designers = DESIGNER_KINDS.map((k) => {
    if (!dk.has(k)) return { id: k, state: "hidden", by: "game", reason: `${a.name} has no ${k} designer` };
    if (!fe?.ok) return { id: k, state: "hidden", by: "version", reason: fe?.error ?? "version not supported by the designers" };
    if (k === "motion" && !profile?.motion) return { id: k, state: "hidden", by: "game", reason: `${a.name} declares no motion lowering` };
    return { id: k, state: "usable" };
  });
  const dOn = (k: DesignerKind) => m.designers.some((d) => d.id === k && d.state === "usable");
  if (fe?.ok) {
    const ents = vanillaIds("entity_type", version);
    m.palette = {
      triggers: [...TRIGGER_TYPES], conditions: [...CONDITION_TYPES], actions: Object.keys(ACTION_TEMPLATES),
      projectiles: PROJECTILES.filter((p) => !ents.size || ents.has(p)),
      itemStates: fe.features.itemModel,
      animatedCreatures: cap("animatedCreatures"),
    };
    if (!fe.features.itemModel) addWhy({ id: "item-states", title: "Item model states (pull, aim, modes)", reason: `They need ${a.name} 1.21.4 or newer; ${version} only has worn-down looks through custom model data.`, by: "version" });
  }
  if (kindOk("model") && !cap("animatedCreatures") && a.routeRules.some((r) => r.requiresCapability?.capability === "animatedCreatures")) {
    addWhy({ id: "animated-creatures", title: "Animated custom creatures", reason: `They need ${a.name} 26.x; on ${version} creatures use a vanilla-looking mob with custom sounds.`, by: "version" });
  }

  // studios
  const sw = (id: StudioId) => ctx.switches?.[id] !== false;
  const hiddenGame = (id: StudioId, reason: string): Entry<StudioId> => ({ id, state: "hidden", by: "game", reason });
  const studio = (id: StudioId): Entry<StudioId> => {
    switch (id) {
      case "code": return { id, state: "usable" };
      case "items": return dOn("item") ? { id, state: "usable" } : hiddenGame(id, m.designers.find((d) => d.id === "item")!.reason!);
      case "menus": return dOn("menu") || dOn("quest") ? { id, state: "usable" } : hiddenGame(id, `${a.name} has no menu or quest designer`);
      case "bosses": return dOn("boss") ? { id, state: "usable" } : hiddenGame(id, `${a.name} has no boss designer`);
      case "motion": return dOn("motion") ? { id, state: "usable" } : hiddenGame(id, `${a.name} declares no motion lowering`);
      case "datapacks": return m.routes.find((r) => r.id === "dataPack")!.state === "usable" ? { id, state: "usable" } : hiddenGame(id, `${a.name} has no data packs`);
      case "texture": return kindOk("texture") ? { id, ...gate("texture") } : hiddenGame(id, a.assetDelivery.texture.note);
      case "sound": return kindOk("sound") ? { id, ...gate("sound") } : hiddenGame(id, a.assetDelivery.sound.note);
      case "model": return kindOk("model") && (profile?.meshFormats.length ?? 0) > 0 ? { id, ...gate("model") } : hiddenGame(id, `${a.name} takes no custom models`);
      case "model-editor": return kindOk("model") && !!profile?.meshFormats.includes("bbmodel") ? { id, ...gate("model") } : hiddenGame(id, `${a.name} has no cuboid/bone models`);
      case "mesh": return kindOk("model") && !!profile?.meshBudget ? { id, ...gate("model") } : hiddenGame(id, profile?.catalog?.noneReasons?.model ?? `${a.name} takes no 3D meshes`);
      case "config": { const e = exporterFor(a.game); return e && e.maturity !== "planned" ? { id, state: "usable" } : hiddenGame(id, `the ${a.name} settings exporter is planned, not built`); }
      case "library": return CATALOG_KINDS.some((k) => (accepts[k] ?? "none") !== "none") ? { id, state: "usable" } : hiddenGame(id, `${a.name} declares no library assets it can use`);
    }
  };
  m.studios = STUDIO_IDS.map((id) => {
    const e = studio(id);
    return sw(id) ? e : { id, state: "hidden", by: "switch" };
  });
  if (m.studios.find((s) => s.id === "mesh")?.by === "game") addWhy({ id: "meshes", title: "3D meshes (glTF), PBR texture sets, HDRI skies, decals", reason: profile?.catalog?.noneReasons?.model ?? `${a.name} takes no 3D meshes.`, by: "game" });

  // library kinds (the catalog fit hints: none = the game cannot use the kind)
  m.libraryKinds = CATALOG_KINDS.map((k) => {
    const mode = accepts[k] ?? "none";
    if (mode === "none") return { id: k, state: "hidden", by: "game", reason: profile?.catalog?.noneReasons?.[k] ?? `${a.name} cannot use ${k} assets` };
    return planGiven ? { id: k, ...gate(k === "sound" || k === "music" ? "sound" : k === "texture" || k === "sprite" || k === "flipbook" || k === "particle-texture" ? "texture" : "model") } : { id: k, state: "usable" };
  });

  // client-only features (the adapter's own route rules onto an unsupported route)
  for (const r of a.routeRules) {
    const art = r.route ? a.artifacts.find((x) => x.route === r.route) : undefined;
    if (art?.availability === "unsupported" && r.limit) addWhy({ id: r.id, title: RULE_TITLE[r.id] ?? human(r.id), reason: r.limit.message, by: "game" });
  }

  // parts a mod of this game can have
  const parts = new Set<PartKind>(["code"]);
  if (dOn("item")) parts.add("items");
  if (dOn("menu")) parts.add("menus");
  if (dOn("quest")) parts.add("quests");
  if (dOn("boss")) parts.add("bosses");
  if (dOn("hud")) parts.add("hud");
  if (dOn("motion")) parts.add("motions");
  if (kindOk("texture")) parts.add("textures");
  if (kindOk("sound")) parts.add("sounds");
  if (kindOk("model")) { parts.add("models"); parts.add("creatures"); }
  if (m.studios.find((s) => s.id === "config")?.state !== "hidden") parts.add("config");
  if (m.routes.find((r) => r.id === "dataPack")?.state === "usable") { parts.add("datapack"); parts.add("worldgen"); }
  m.partKinds = PART_KINDS.filter((k) => parts.has(k));

  // templates + example prompts
  m.templates = CYRUS_TEMPLATES.filter((t) => t.games.includes(a.game) && (t.needs ?? []).every((s) => m.studios.find((x) => x.id === s)?.state !== "hidden"));
  m.examplePrompts = [...(SUPPORT[a.game]?.examplePrompts ?? [])];
  m.whyNot = whyNot;
  return m;
}

/** State of one studio (hidden when the manifest does not list it). */
export const studioState = (m: CapabilityManifest, id: StudioId): Avail => m.studios.find((s) => s.id === id)?.state ?? "hidden";
/** The studios to SHOW (usable + locked), in manifest order. */
export const shownStudios = (m: CapabilityManifest) => m.studios.filter((s) => s.state !== "hidden");
/** Library kinds the game can use (usable or plan-locked); hidden kinds are never searched or listed. */
export const gameLibraryKinds = (m: CapabilityManifest): CatalogKind[] => m.libraryKinds.filter((k) => k.state !== "hidden").map((k) => k.id);
/** A compact map for the client (StudioMod.studios). */
export const studioStates = (m: CapabilityManifest): Partial<Record<StudioId, Avail>> => Object.fromEntries(m.studios.map((s) => [s.id, s.state]));

