import type { Metadata } from "next";
import { CYRUS_GAMES } from "@/lib/cyrus/games";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { buildTokenState } from "@/lib/cyrus/tokens/state";
import { NewModFlow, type CostInfo } from "@/components/cyrus/app/NewModFlow";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { appViewer, P } from "../_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus · New mod", robots: { index: false } };

/** New-mod flow (r39). The build itself is created by the existing build API, which re-checks everything. */
export default async function CyrusNewMod() {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  const [servers, tokens] = await Promise.all([modBuilderServers(v.user.id).catch(() => []), buildTokenState(v.user).catch(() => null)]);
  const cost: CostInfo = tokens?.active
    ? { active: true, enforce: tokens.enforce, available: tokens.available, models: tokens.models, reserve: tokens.reserve }
    : { active: false, enforce: false, available: 0, models: [], reserve: null };
  return (
    <>
      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">New mod</div>
          <h1 className="cx-h1">What should Cyrus <span className="cx-grad">build</span>?</h1>
          <p className="cx-sub">Pick where it runs and see what it costs before anything starts.</p>
        </div>
      </header>
      <NewModFlow games={CYRUS_GAMES} servers={servers} cost={cost} projectBase={v.href(P.projects)} studioHref={v.onCyrus ? "/studio" : "/dashboard/cyrus"} />
    </>
  );
}

