// the studio pages apply. A switched-off studio is hidden with no "why not" line, so a flag never leaks.
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { configStudioViewer } from "@/lib/cyrus/config/deps";
import { designerStudioOn } from "@/lib/cyrus/designer/studio/deps";
import { DATAPACK_STUDIO_FLAG } from "@/lib/cyrus/datapack/studio-view";
import { LIBRARY_BROWSE_FLAG } from "@/lib/cyrus/library/v2/browse";
import type { StudioId } from "@/lib/cyrus/manifest";

export async function studioSwitches(): Promise<Partial<Record<StudioId, boolean>>> {
  const [model, config] = await Promise.all([modelStudioViewer().catch(() => null), configStudioViewer().catch(() => null)]);
  const designer = designerStudioOn();
  return {
    texture: !!model, sound: !!model, model: !!model, "model-editor": !!model, mesh: !!model, motion: !!model && designer,
    items: designer, menus: designer, bosses: designer, config: !!config,
    datapacks: process.env[DATAPACK_STUDIO_FLAG] === "1", library: process.env[LIBRARY_BROWSE_FLAG] === "1",
  };
}
