// Cyrus v8 capability manifest: per game + version, only what the game can use (usable / locked by plan / hidden).
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { usableFor, studioState, shownStudios, gameLibraryKinds, libraryKindsForGame, STUDIO_IDS } from "../lib/cyrus/manifest";
import { CYRUS_TEMPLATES } from "../lib/cyrus/templates";
import { browseCatalog } from "../lib/cyrus/library/v2/browse";
import { catalogSearch } from "../lib/cyrus/library/v2/tools";
import type { CatalogIndex } from "../lib/cyrus/library/v2/retrieval";

const ids = (xs: { id: string; state: string }[], st: string) => xs.filter((x) => x.state === st).map((x) => x.id).sort();

describe("capability manifest: Minecraft", () => {
  const mc = usableFor("minecraft", "1.21.11");
  it("shows the Minecraft studios and hides what Minecraft cannot use", () => {
    assert.equal(mc.level, "full");
    for (const s of ["code", "items", "menus", "bosses", "motion", "datapacks", "texture", "sound", "model", "model-editor", "config", "library"]) assert.equal(studioState(mc, s as never), "usable", s);
    assert.equal(studioState(mc, "mesh"), "hidden", "no mesh route: Minecraft takes no glTF meshes");
    assert.equal(mc.studios.find((s) => s.id === "mesh")!.by, "game");
    assert.equal(mc.routes.find((r) => r.id === "clientMod")!.state, "hidden");
  });
  it("library kinds come from the catalog hints: no meshes, PBR sets, HDRIs or decals", () => {
    const k = gameLibraryKinds(mc);
    for (const x of ["sound", "music", "texture", "sprite", "motion-preset", "effect-preset"]) assert.ok(k.includes(x as never), x);
    for (const x of ["model", "texture-set", "hdri", "decal", "animation-clip", "animated-model"]) assert.ok(!k.includes(x as never), x);
  });
  it("why-not lines name the client-only features (shaders, keybinds...) and meshes", () => {
    const w = mc.whyNot.map((x) => x.id);
    for (const x of ["custom_sky", "keybind", "freeform_hud", "custom_block", "meshes"]) assert.ok(w.includes(x), x);
    assert.ok(!w.includes("item-states"), "1.21.11 has item states");
    assert.ok(mc.whyNot.find((x) => x.id === "custom_sky")!.reason.includes("client mod"));
  });
  it("version facts: 1.21.1 hides item model states, 26.x has animated creatures", () => {
    const old = usableFor("minecraft", "1.21.1");
    assert.equal(old.palette!.itemStates, false);
    assert.ok(old.whyNot.some((x) => x.id === "item-states" && x.by === "version"));
    assert.equal(mc.palette!.itemStates, true);
    assert.equal(mc.palette!.animatedCreatures, false);
    assert.ok(mc.whyNot.some((x) => x.id === "animated-creatures"));
    assert.equal(usableFor("minecraft", "26.2").palette?.animatedCreatures ?? true, true);
  });
  it("plan locks only what the game can use; hidden stays hidden", () => {
    const free = usableFor("minecraft", "1.21.11", { plan: "free" });
    assert.equal(studioState(free, "texture"), "locked");
    assert.equal(free.studios.find((s) => s.id === "texture")!.needs, "all");
    assert.equal(studioState(free, "sound"), "locked");
    assert.equal(studioState(free, "mesh"), "hidden");
    assert.equal(studioState(free, "items"), "usable", "designers are not plan-gated");
    assert.equal(studioState(usableFor("minecraft", "1.21.11", { plan: null }), "texture"), "locked", "unknown plan fails closed");
    assert.equal(studioState(usableFor("minecraft", "1.21.11", { plan: "saka" }), "sound"), "usable");
  });
  it("host switches hide with no why-not line", () => {
    const m = usableFor("minecraft", "1.21.11", { switches: { model: false, items: false } });
    assert.equal(studioState(m, "model"), "hidden");
    assert.equal(m.studios.find((s) => s.id === "items")!.by, "switch");
    assert.ok(!shownStudios(m).some((s) => s.id === "model"));
  });
  it("templates are the Minecraft gallery; parts include designs and assets", () => {
    assert.equal(mc.templates.length, CYRUS_TEMPLATES.filter((t) => t.games.includes("minecraft")).length);
    for (const p of ["items", "quests", "bosses", "textures", "sounds", "config", "datapack"]) assert.ok(mc.partKinds.includes(p as never), p);
    assert.ok(mc.examplePrompts.length > 0);
  });
});

describe("capability manifest: code-only games never see Minecraft things", () => {
  for (const game of ["terraria", "valheim", "zomboid"]) {
    it(game, () => {
      const m = usableFor(game, "x");
      assert.equal(m.level, "code-only");
      assert.deepEqual(ids(m.studios, "usable"), ["code"]);
      assert.equal(ids(m.studios, "hidden").length, STUDIO_IDS.length - 1);
      assert.equal(m.designers.every((d) => d.state === "hidden"), true);
      assert.equal(gameLibraryKinds(m).length, 0);
      assert.equal(m.templates.length, 0, "the Paper templates are Minecraft only");
      assert.ok(m.examplePrompts.length > 0, "own example prompts");
      assert.ok(!m.examplePrompts.some((p) => /minecraft|paper/i.test(p)));
      assert.ok(m.whyNot.length >= 2);
      assert.deepEqual(m.partKinds, ["code"]);
    });
  }
  it("an unknown game gets an empty manifest (fail closed)", () => {
    const m = usableFor("nosuchgame", "1");
    assert.equal(m.known, false);
    assert.equal(m.studios.length, 0);
    assert.equal(libraryKindsForGame("nosuchgame")!.usable.length, 0);
    assert.equal(libraryKindsForGame(null), null);
  });
});

describe("capability manifest applied to the library", () => {
  const seen: { kinds?: string[] }[] = [];
  const index = { search: async (q: { kinds?: string[] }) => { seen.push(q); return { total: 0, hits: [] }; }, get: async () => null } as unknown as CatalogIndex;
  it("browse never searches or lists as locked a kind Minecraft cannot use", async () => {
    const r = await browseCatalog({ game: "minecraft" }, { index, plan: "all", proprietaryCleared: true });
    assert.ok(!r.kinds.includes("model") && !r.kinds.includes("hdri"));
    assert.ok(!r.locked.some((l) => l.kind === "model"));
    assert.ok(r.hidden!.some((h) => h.kind === "hdri"));
    assert.ok(!seen.at(-1)!.kinds!.includes("model"));
    const one = await browseCatalog({ game: "minecraft", kind: "model" }, { index, plan: "all", proprietaryCleared: true });
    assert.match(one.notice ?? "", /do not work in this game/);
  });
  it("catalog_search drops unusable kinds for the model too", async () => {
    const r = await catalogSearch({ query: "crate", kind: "model" }, { index, plan: "all", game: "minecraft", proprietaryCleared: true });
    assert.equal(r.ok, false);
    assert.match(r.content, /kind_unusable/);
    const t = await catalogSearch({ query: "sword" }, { index, plan: "all", game: "terraria", proprietaryCleared: true });
    assert.match(t.content, /kind_unusable/);
  });
});

