// esbuild entry of services/modbuilder/designer-spec.js: the build service's copy of the gameplay designer validator and
// compiler, GENERATED from these TypeScript files (one source of truth; test/cyrus-designer.test.ts checks the file is
// current and gives the same results as the TypeScript).
export { validateDesign, validateDesigns, designFeatures, canonicalJson, DESIGN_LIMITS, DESIGN_SPEC_VERSION, CAPS, BUDGET, DESIGN_CHECKS } from "./spec";
export { compileDesigns, COMPILER_VERSION, designParams } from "./compile";
export { planDesignEdit, applyParameterEdits } from "./params";
export { libraryHash, COMPONENT_LIBRARY_VERSION } from "./components";
// R3 menus + quests (the same `design` files with a kind discriminator)
export { validateGameplay, designKind, GAMEPLAY_LIMITS, GAMEPLAY_CAPS, GAMEPLAY_SPEC_VERSION } from "./gameplay/spec";
export { compileMod, GAMEPLAY_COMPILER_VERSION } from "./gameplay/compile";
export { applyGameplayEdits } from "./gameplay/params";
export { gameplayLibraryHash, GAMEPLAY_LIBRARY_VERSION } from "./gameplay/components";
// R3 bosses + encounters (kind "boss" / "encounter", validated and compiled through validateGameplay / compileMod)
export { BOSS_LIMITS, BOSS_CAPS, BOSS_SPEC_VERSION } from "./boss/spec";
export { BOSS_COMPILER_VERSION } from "./boss/compile";
export { bossLibraryHash, BOSS_LIBRARY_VERSION } from "./boss/components";
// R4 glyph HUDs (kind "hud")
export { HUD_LIMITS, HUD_SPEC_VERSION, allocateHudGlyphs } from "./hud/spec";
export { HUD_COMPILER_VERSION } from "./hud/compile";
export { hudLibraryHash, HUD_LIBRARY_VERSION } from "./hud/components";
// motion designs ("kind": "motion": a MotionSpec or a motion-library preset + the Minecraft binding; ../motion)
export { validateMotionDesign, MOTION_DESIGN_LIMITS, MOTION_DESIGN_VERSION } from "./motion/spec";
export { MOTION_COMPILER_VERSION, MOTION_LIBRARY_VERSION, motionLibraryHash } from "./motion/compile";
export { MOTION_PRESETS_BRIEF } from "./motion/brief";
  const read = (dir) => { try { return fs.readdirSync(path.join(ws, dir)).filter((n) => /^[a-z][a-z0-9_]{1,31}\.json$/.test(n)).sort(); } catch { return []; } };
  for (const n of read("assets/textures")) models.push(`${namespace}:${n.slice(0, -5)}`);
  for (const n of read("assets/sounds")) {
    try { const s = JSON.parse(fs.readFileSync(path.join(ws, "assets/sounds", n), "utf8")); for (const e of (s && Array.isArray(s.events) ? s.events : [])) if (e && typeof e.event === "string") sounds.push(`${namespace}:${n.slice(0, -5)}.${e.event}`); } catch { /* unreadable spec: no keys */ }
  }
  // R3 quest rewards: advancements of this project's data pack specs (assets/datapack/<name>.json resources)
  for (const n of read("assets/datapack")) {
    try { const s = JSON.parse(fs.readFileSync(path.join(ws, "assets/datapack", n), "utf8")); for (const r of (s && Array.isArray(s.resources) ? s.resources : [])) { if (r && r.type === "advancement" && typeof r.id === "string") advancements.push(`${namespace}:${r.id}`); if (r && r.type === "loot_table" && typeof r.id === "string") lootTables.push(`${namespace}:${r.id}`); } } catch { /* unreadable spec: no keys */ }
  }
  const itemModels = mcVersion ? IMS.itemModelNeedsOf(ws, namespace, mcVersion) : {};
  return { models, sounds, advancements, lootTables, ...(Object.keys(itemModels).length ? { itemModels } : {}) };
}

/**
 * Validate every design in the workspace (same contract as checkWorkspaceDatapacks):
 *   problems (HARD): invalid JSON / design, file name != id, cross-file duplicates, more files than allowed. Dropped after
 *   the bounded repairs, never shipped. soft: warnings worth one repair round (unresolved asset keys are only warnings).
 */
function checkWorkspaceDesigns(ws, { namespace, mcVersion }) {
  const files = listDesignFiles(ws);
  const results = [];
  const problems = [];
