// Cyrus engine core, v8 structure: ModSpec v2 = a mod made of MODULES (parts). One mod, one namespace, one jar; modules
// reference each other (a quest line needs a creature and an item) and can be edited, built, flown and exported alone.
// DISTINCT from Mod Packs (lib/cyrus/modpack: several separate mods installed together through the conflict engine).
// Pure + client-safe (no node APIs; fingerprints are FNV-1a, a change detector, not a security hash). Flag
// CYRUS_MOD_SUITES (off): v1 stays the engine default; the store accepts v2 only while the flag is on.
// Design: /root/agent-notes/cyrus-designs/v8-structure/STRUCTURE-PLAN.md sections 3-6.
import { z } from "zod";
import { ModSpecV1Schema, migrateSpec, validateModSpec, SLOT_ID_RE, REQ_ID_RE, type ModSpec, type SpecIssue, type ValidateOptions, type SpecMigration, type Requirement } from "./spec";
import { NAMESPACE_RE } from "./identifiers";

export const MOD_SUITES_FLAG = "CYRUS_MOD_SUITES";
export const modSuitesOn = (env: Record<string, string | undefined> = process.env) => env[MOD_SUITES_FLAG] === "1";
export const SPEC_V2 = 2 as const;

export const MODULE_KINDS = ["items", "creatures", "quests", "menus", "bosses", "hud", "textures", "sounds", "models", "motions", "config", "datapack", "worldgen", "code"] as const;
export type ModuleKind = (typeof MODULE_KINDS)[number];
/** What a module can provide to others: `<kind>:<id>` (the id lives in the project's one namespace). */
export const PROVIDE_KINDS = ["item", "entity", "quest", "menu", "boss", "encounter", "hud", "motion", "sound", "texture", "model", "recipe", "loot", "advancement", "function", "config"] as const;
export const PROVIDE_RE = new RegExp(`^(${PROVIDE_KINDS.join("|")}):[a-z][a-z0-9_]{0,47}$`);
/** Suite caps (flag on). Runtime caps of the designers (live bosses, tasks, per-activation budgets) do NOT grow. */
export const SUITE_LIMITS = { maxModules: 32, maxDesignsPerModule: 40, maxProvides: 64, maxDepends: 16 } as const;
/** Module file ownership: prefixes of project paths the module owns (custom code, extra resources). */
const PATH_PREFIX_RE = /^[a-zA-Z0-9_.-]+(\/[a-zA-Z0-9_.-]+)*\/?$/;

export const ModuleZ = z.object({
  id: z.string().regex(SLOT_ID_RE, "module ids are lowercase letters, digits and underscores"),
  kind: z.enum(MODULE_KINDS),
  title: z.string().trim().min(1).max(80),
  summary: z.string().trim().max(500).optional(),
  /** Takes every design and asset slot no other module lists (a migrated v1 spec has one such module). */
  default: z.boolean().optional(),
  dependsOn: z.array(z.string().regex(SLOT_ID_RE)).max(SUITE_LIMITS.maxDepends).default([]),
  requirementIds: z.array(z.string().regex(REQ_ID_RE)).max(100).default([]),
  /** Asset slot ids (ModSpec assets[].id) of this module. */
  assets: z.array(z.string().regex(SLOT_ID_RE)).max(200).default([]),
  /** Design ids (assets/designs/<id>.json) of this module. */
  designs: z.array(z.string().regex(/^[a-z][a-z0-9_]{1,31}$/)).max(SUITE_LIMITS.maxDesignsPerModule).default([]),
  files: z.array(z.string().max(200).regex(PATH_PREFIX_RE)).max(20).default([]),
  provides: z.array(z.string().regex(PROVIDE_RE, "provides are <kind>:<id>, e.g. item:frost_blade")).max(SUITE_LIMITS.maxProvides).default([]),
  uses: z.array(z.string().regex(PROVIDE_RE)).max(SUITE_LIMITS.maxProvides).default([]),
}).strict();
export type ModSpecModule = z.output<typeof ModuleZ>;

export const ModSpecV2Schema = ModSpecV1Schema.extend({
  schemaVersion: z.literal(2),
  modules: z.array(ModuleZ).min(1).max(SUITE_LIMITS.maxModules),
}).strict();
export type ModSpecV2 = z.output<typeof ModSpecV2Schema>;

// ------------------------------------------------------------------------------------------------ migration v1 -> v2
/** The module kind a v1 spec most looks like (one module). */
function mainKind(doc: Record<string, unknown>): ModuleKind {
  const routes = Array.isArray(doc.routes) ? doc.routes : [];
  const kinds = new Set((Array.isArray(doc.assets) ? doc.assets : []).map((a) => (a as { kind?: string })?.kind));
  if (routes.length === 1 && routes[0] === "dataPack") return "datapack";
  if (routes.includes("plugin")) return "code";
  if (kinds.size === 1 && kinds.has("texture")) return "textures";
  if (kinds.size === 1 && kinds.has("sound")) return "sounds";
  return "code";
}
/** v1 -> v2: the whole spec becomes ONE default module `main`. Lossless (toV1 gives the v1 doc back). */
export const migrateV1ToV2: SpecMigration = (doc) => ({
  ...doc,
  modules: [{
    id: "main", kind: mainKind(doc), title: typeof doc.summary === "string" ? doc.summary.slice(0, 60).replace(/\s+\S*$/, "") || "Main" : "Main", default: true,
    dependsOn: [], requirementIds: (Array.isArray(doc.requirements) ? doc.requirements : []).map((r) => (r as { id?: string })?.id).filter((x): x is string => typeof x === "string"),
    assets: [], designs: [], files: [], provides: [], uses: [],
  }],
});
export const SPEC_V2_MIGRATIONS: Readonly<Record<number, SpecMigration>> = { 1: migrateV1ToV2 };

/** v2 -> v1 (drops modules): for every consumer still on v1. */
export function toV1(spec: ModSpecV2): ModSpec {
  const { modules: _m, ...rest } = spec;
  return { ...rest, schemaVersion: 1 } as ModSpec;
}

// ------------------------------------------------------------------------------------------------ validation
/** A design file as the validator sees it: id + kind + the JSON (references inside are extracted). */
export type DesignRef = { id: string; kind: string; json?: unknown };
export type ModulesResult = { errors: SpecIssue[]; warnings: SpecIssue[] };

const DESIGN_PROVIDE: Record<string, string> = { item: "item", menu: "menu", quest: "quest", boss: "boss", encounter: "encounter", hud: "hud", motion: "motion" };
/** What a design file provides by being in a module. */
export const designProvide = (d: DesignRef) => `${DESIGN_PROVIDE[d.kind] ?? "item"}:${d.id}`;

/** Every `<ns>:<id>` string inside a design (ids of this mod's other designs or asset slots). */
export function designReferences(json: unknown, ns: string): string[] {
  const out = new Set<string>();
  const re = new RegExp(`^${ns}:([a-z][a-z0-9_]*)`);
  const walk = (x: unknown, depth: number) => {
    if (depth > 24) return;
    if (typeof x === "string") { const m = re.exec(x); if (m) out.add(m[1]); }
    else if (Array.isArray(x)) for (const y of x) walk(y, depth + 1);
    else if (x && typeof x === "object") for (const y of Object.values(x)) walk(y, depth + 1);
  };
  walk(json, 0);
  return [...out].sort();
}

/** Transitive dependencies of a module (not including itself). Cycles are tolerated (validation reports them). */
export function dependencyClosure(modules: readonly Pick<ModSpecModule, "id" | "dependsOn">[], id: string): string[] {
  const by = new Map(modules.map((m) => [m.id, m]));
  const seen = new Set<string>();
  const stack = [...(by.get(id)?.dependsOn ?? [])];
  while (stack.length) { const x = stack.pop()!; if (x === id || seen.has(x)) continue; seen.add(x); stack.push(...(by.get(x)?.dependsOn ?? [])); }
  return [...seen].sort();
}

/** Modules that (transitively) depend on `id`. */
export const dependents = (modules: readonly Pick<ModSpecModule, "id" | "dependsOn">[], id: string) => modules.filter((m) => m.id !== id && dependencyClosure(modules, m.id).includes(id)).map((m) => m.id);

/** The first dependency cycle, as a path a -> b -> a, or null. */
export function findCycle(modules: readonly Pick<ModSpecModule, "id" | "dependsOn">[]): string[] | null {
  const by = new Map(modules.map((m) => [m.id, m]));
  const state = new Map<string, 1 | 2>();
  const path: string[] = [];
  const visit = (id: string): string[] | null => {
    state.set(id, 1); path.push(id);
    for (const d of by.get(id)?.dependsOn ?? []) {
      if (!by.has(d)) continue;
      if (state.get(d) === 1) return [...path.slice(path.indexOf(d)), d];
      if (!state.has(d)) { const c = visit(d); if (c) return c; }
    }
    path.pop(); state.set(id, 2); return null;
  };
  for (const m of modules) if (!state.has(m.id)) { const c = visit(m.id); if (c) return c; }
  return null;
}

/** Module that owns each design / asset slot (explicit membership, then the default module). */
export function ownership(spec: Pick<ModSpecV2, "modules" | "assets">, designs: readonly DesignRef[] = []) {
  const design = new Map<string, string>();
  const slot = new Map<string, string>();
  for (const m of spec.modules) { for (const d of m.designs) if (!design.has(d)) design.set(d, m.id); for (const a of m.assets) if (!slot.has(a)) slot.set(a, m.id); }
  const def = spec.modules.find((m) => m.default)?.id;
  if (def) { for (const d of designs) if (!design.has(d.id)) design.set(d.id, def); for (const a of spec.assets) if (!slot.has(a.id)) slot.set(a.id, def); }
  return { design, slot, defaultModule: def ?? null };
}

/** Every provide of a module: its declared provides + one per design it owns. */
export function providesOf(spec: Pick<ModSpecV2, "modules" | "assets">, designs: readonly DesignRef[], id: string): string[] {
  const own = ownership(spec, designs);
  const m = spec.modules.find((x) => x.id === id);
  const fromDesigns = designs.filter((d) => own.design.get(d.id) === id).map(designProvide);
  return [...new Set([...(m?.provides ?? []), ...fromDesigns])].sort();
}

/**
 * Cross-reference rules (structured issues, never throws): ids, dangling dependsOn / assets / designs / requirements,
 * self-dependency, cycles, double ownership, duplicate provides, uses that nobody provides (dangling) or that come
 * from a module not in the dependency closure (missing dependency), and the same for references found INSIDE designs.
 */
export function validateModules(spec: Pick<ModSpecV2, "modules" | "assets" | "requirements" | "namespace">, designs: readonly DesignRef[] = []): ModulesResult {
  const errors: SpecIssue[] = [];
  const warnings: SpecIssue[] = [];
  const err = (path: string, code: string, message: string) => errors.push({ path, code, message });
  const ms = spec.modules;
  const ids = new Set<string>();
  ms.forEach((m, i) => { if (ids.has(m.id)) err(`modules[${i}].id`, "duplicate_module", `module ${m.id} is listed twice`); ids.add(m.id); });
  if (ms.filter((m) => m.default).length > 1) err("modules", "two_defaults", "only one module can take the unassigned parts (default)");
  const slots = new Set(spec.assets.map((a) => a.id));
  const reqs = new Set(spec.requirements.map((r) => r.id));
  const dIds = new Set(designs.map((d) => d.id));
  const slotOwner = new Map<string, string>();
  const designOwner = new Map<string, string>();
  ms.forEach((m, i) => {
    m.dependsOn.forEach((d, j) => {
      if (d === m.id) err(`modules[${i}].dependsOn[${j}]`, "self_dependency", `${m.id} depends on itself`);
      else if (!ids.has(d)) err(`modules[${i}].dependsOn[${j}]`, "dangling_dependency", `${m.id} depends on ${d}, which is not a module of this mod`);
    });
    m.requirementIds.forEach((r, j) => { if (!reqs.has(r)) err(`modules[${i}].requirementIds[${j}]`, "unknown_requirement", `${m.id} points at ${r}, which is not a requirement`); });
    m.assets.forEach((a, j) => {
      if (!slots.has(a)) err(`modules[${i}].assets[${j}]`, "dangling_asset", `${m.id} lists asset ${a}, which is not an asset slot of this mod`);
      const o = slotOwner.get(a); if (o && o !== m.id) err(`modules[${i}].assets[${j}]`, "asset_in_two_modules", `asset ${a} belongs to both ${o} and ${m.id}`); slotOwner.set(a, m.id);
    });
    m.designs.forEach((d, j) => {
      if (designs.length && !dIds.has(d)) err(`modules[${i}].designs[${j}]`, "dangling_design", `${m.id} lists design ${d}, which is not a design file of this mod`);
      const o = designOwner.get(d); if (o && o !== m.id) err(`modules[${i}].designs[${j}]`, "design_in_two_modules", `design ${d} belongs to both ${o} and ${m.id}`); designOwner.set(d, m.id);
    });
  });
  const cyc = findCycle(ms);
  if (cyc) err("modules", "dependency_cycle", `modules depend on each other in a circle: ${cyc.join(" -> ")}`);
  const own = ownership(spec, designs);
  if (!own.defaultModule) {
    for (const a of spec.assets) if (!own.slot.has(a.id)) warnings.push({ path: "modules", code: "unassigned_asset", message: `asset ${a.id} belongs to no module` });
    for (const d of designs) if (!own.design.has(d.id)) warnings.push({ path: "modules", code: "unassigned_design", message: `design ${d.id} belongs to no module` });
  }
  // provides: unique across modules
  const provider = new Map<string, string>();
  for (const m of ms) for (const p of providesOf(spec, designs, m.id)) {
    const o = provider.get(p);
    if (o && o !== m.id) err(`modules.${m.id}.provides`, "duplicate_provide", `${p} is provided by both ${o} and ${m.id}`);
    else provider.set(p, m.id);
  }
  const byId = (x: string) => [...provider.entries()].filter(([p]) => p.slice(p.indexOf(":") + 1) === x).map(([p, mod]) => ({ p, mod }));
  const check = (user: string, ref: string, path: string, how: string) => {
    const hits = ref.includes(":") ? (provider.has(ref) ? [{ p: ref, mod: provider.get(ref)! }] : []) : byId(ref);
    if (!hits.length) { if (ref.includes(":")) err(path, "dangling_reference", `${user} ${how} ${ref}, which no module provides`); return; }
    if (hits.some((h) => h.mod === user)) return;
    const closure = dependencyClosure(ms, user);
    if (!hits.some((h) => closure.includes(h.mod))) err(path, "missing_dependency", `${user} ${how} ${hits[0].p} from ${hits[0].mod} but does not depend on it (add ${hits[0].mod} to its dependencies)`);
  };
  ms.forEach((m, i) => m.uses.forEach((u, j) => check(m.id, u, `modules[${i}].uses[${j}]`, "uses")));
  // references inside designs: ids of other designs or asset slots of this mod
  if (NAMESPACE_RE.test(spec.namespace)) for (const d of designs) {
    const user = own.design.get(d.id);
    if (!user || d.json === undefined) continue;
    for (const ref of designReferences(d.json, spec.namespace)) {
      if (ref === d.id) continue;
      if (dIds.has(ref)) { const o = own.design.get(ref); if (o && o !== user && !dependencyClosure(ms, user).includes(o)) err(`designs.${d.id}`, "missing_dependency", `${d.kind} ${d.id} (in ${user}) uses ${ref} from ${o} but ${user} does not depend on ${o}`); continue; }
      const base = ref.split(".")[0];
      const so = own.slot.get(base);
      if (so && so !== user && !dependencyClosure(ms, user).includes(so)) err(`designs.${d.id}`, "missing_dependency", `${d.kind} ${d.id} (in ${user}) uses asset ${base} from ${so} but ${user} does not depend on ${so}`);
    }
  }
  for (const m of ms) if (!m.designs.length && !m.assets.length && !m.files.length && !m.provides.length && !m.default) warnings.push({ path: `modules.${m.id}`, code: "empty_module", message: `${m.id} has no designs, assets, files or provides yet` });
  return { errors, warnings };
}

export type ValidateV2Result =
  | { ok: true; spec: ModSpecV2; warnings: SpecIssue[]; migratedFrom: number }
  | { ok: false; errors: SpecIssue[]; warnings: SpecIssue[] };

const pathOf = (p: readonly PropertyKey[]) => p.map((k) => (typeof k === "number" ? `[${k}]` : `.${String(k)}`)).join("").replace(/^\./, "");

/** Untrusted JSON (v1 or v2) -> ModSpecV2, or every problem: the v1 rules on the shared fields + the module rules. */
export function validateModSpecV2(raw: unknown, opts: ValidateOptions & { designs?: readonly DesignRef[] } = {}): ValidateV2Result {
  const mig = migrateSpec(raw, SPEC_V2_MIGRATIONS, SPEC_V2);
  if (!mig.ok) return { ok: false, errors: mig.errors, warnings: [] };
  const parsed = ModSpecV2Schema.safeParse(mig.doc);
  if (!parsed.success) return { ok: false, warnings: [], errors: parsed.error.issues.map((i) => ({ path: pathOf(i.path), code: i.code, message: i.message })) };
  const { modules: _m, ...v1doc } = mig.doc as Record<string, unknown>;
  const v1 = validateModSpec({ ...v1doc, schemaVersion: 1 }, { adapterFor: opts.adapterFor });
  const mods = validateModules(parsed.data, opts.designs ?? []);
  const warnings = [...v1.warnings, ...mods.warnings];
  const errors = [...(v1.ok ? [] : v1.errors), ...mods.errors];
  return errors.length ? { ok: false, errors, warnings } : { ok: true, spec: parsed.data, warnings, migratedFrom: mig.from };
}

// ------------------------------------------------------------------------------------------------ scoped change
export type Scope = { kind: "whole" } | { kind: "module"; id: string };
export const scopeLabel = (s: Scope) => (s.kind === "whole" ? "whole mod" : `module ${s.id}`);

/** The config.yml key prefixes a design kind writes (the designer compilers' own bases). */
export const CONFIG_BASE: Record<string, string> = { item: "items", menu: "menus", quest: "quests", boss: "bosses", encounter: "encounters", hud: "huds", motion: "motions" };

export type ScopedPlan = {
  scope: Scope;
  /** What the change MAY touch. */
  may: { designs: string[]; assets: string[]; files: string[]; configPrefixes: string[] };
  /** Read-only context: the interfaces of its dependencies and what its dependents use of it. */
  interfaces: { module: string; title: string; provides: string[] }[];
  dependents: { module: string; uses: string[] }[];
  requirements: Requirement[];
  /** Characters of context the scoped prompt carries (so it stays small); measured on the JSON below. */
  contextChars: number;
};

/** What a prompt scoped to `scope` may change and what it sees read-only. */
export function planScopedChange(spec: ModSpecV2, scope: Scope, designs: readonly DesignRef[] = []): ScopedPlan | { error: string } {
  const own = ownership(spec, designs);
  if (scope.kind === "whole") {
    const all = { designs: designs.map((d) => d.id), assets: spec.assets.map((a) => a.id), files: ["*"], configPrefixes: ["*"] };
    return { scope, may: all, interfaces: [], dependents: [], requirements: spec.requirements, contextChars: JSON.stringify(spec).length };
  }
  const m = spec.modules.find((x) => x.id === scope.id);
  if (!m) return { error: `no module ${scope.id}` };
  const mine = designs.filter((d) => own.design.get(d.id) === m.id);
  const may = {
    designs: mine.map((d) => d.id).sort(),
    assets: spec.assets.filter((a) => own.slot.get(a.id) === m.id).map((a) => a.id).sort(),
    files: [...m.files].sort(),
    configPrefixes: mine.map((d) => `${CONFIG_BASE[d.kind] ?? "items"}.${d.id}.`).sort(),
  };
  const interfaces = dependencyClosure(spec.modules, m.id).map((id) => ({ module: id, title: spec.modules.find((x) => x.id === id)!.title, provides: providesOf(spec, designs, id) }));
  const myProvides = new Set(providesOf(spec, designs, m.id));
  const myIds = new Set([...myProvides].map((p) => p.slice(p.indexOf(":") + 1)));
  const deps = dependents(spec.modules, m.id).map((id) => {
    const u = spec.modules.find((x) => x.id === id)!;
    const viaDesigns = designs.filter((d) => own.design.get(d.id) === id).flatMap((d) => designReferences(d.json, spec.namespace)).filter((r) => myIds.has(r));
    return { module: id, uses: [...new Set([...u.uses.filter((x) => myProvides.has(x)), ...viaDesigns])].sort() };
  }).filter((d) => d.uses.length);
  const requirements = spec.requirements.filter((r) => m.requirementIds.includes(r.id));
  const context = { module: { ...m }, designs: mine.map((d) => d.json), interfaces, dependents: deps, requirements };
  return { scope, may, interfaces, dependents: deps, requirements, contextChars: JSON.stringify(context).length };
}

/** A project source file as the guard sees it (sha256 or any content key). Derived outputs are not listed. */
export type FileState = Readonly<Record<string, string>>;
export type GuardResult = {
  ok: boolean;
  merged: Record<string, string>;
  taken: string[]; kept: string[];
  /** Inside the scope but also changed by hand since base: ours kept. */
  conflicts: string[];
  /** Outside the scope: the build tried to change them; ours kept. */
  violations: string[];
  /** A provide a dependent uses would disappear. */
  breaks: { provide: string; dependent: string }[];
};

const DESIGN_PATH = /^assets\/designs\/([a-z][a-z0-9_]{1,31})\.json$/;
/** True for files that are the SOURCE of a mod part (designs, asset specs, owned files). Generated code is derived. */
export const isSourceOfTruth = (p: string) => DESIGN_PATH.test(p) || p.startsWith("assets/") || p.includes("/custom/");

/** May a scoped change touch this path? */
export function pathInScope(plan: ScopedPlan, p: string): boolean {
  if (plan.scope.kind === "whole") return true;
  const d = DESIGN_PATH.exec(p);
  if (d) return plan.may.designs.includes(d[1]);
  if (plan.may.files.some((f) => p === f || p.startsWith(f.endsWith("/") ? f : `${f}/`))) return true;
  const name = p.split("/").pop()!.replace(/\.[a-z0-9]+$/i, "");
  return p.startsWith("assets/") && plan.may.assets.some((a) => name === a || name.startsWith(`${a}.`) || p.includes(`/${a}/`));
}

/**
 * Three-way guard for a scoped build result: base = the head the build started from, ours = the head now (manual edits
 * may have landed), theirs = the build output. Only source-of-truth files are merged; derived files are rebuilt.
 */
export function guardScopedResult(base: FileState, ours: FileState, theirs: FileState, plan: ScopedPlan, provides?: { before: readonly string[]; after: readonly string[] }): GuardResult {
  const out: GuardResult = { ok: true, merged: {}, taken: [], kept: [], conflicts: [], violations: [], breaks: [] };
  const paths = [...new Set([...Object.keys(base), ...Object.keys(ours), ...Object.keys(theirs)])].filter(isSourceOfTruth).sort();
  for (const p of paths) {
    const b = base[p], o = ours[p], t = theirs[p];
    const keep = () => { if (o !== undefined) out.merged[p] = o; };
    if (t === b) { keep(); continue; } // the build did not touch it
    if (!pathInScope(plan, p)) { keep(); out.violations.push(p); continue; }
    if (o !== b && o !== t) { keep(); out.conflicts.push(p); continue; }
    if (t !== undefined) out.merged[p] = t;
    out.taken.push(p);
  }
  if (provides && plan.scope.kind === "module") {
    const gone = provides.before.filter((p) => !provides.after.includes(p));
    for (const d of plan.dependents) for (const u of d.uses) if (gone.some((g) => g === u || g.endsWith(`:${u}`))) out.breaks.push({ provide: gone.find((g) => g === u || g.endsWith(`:${u}`))!, dependent: d.module });
  }
  out.kept = paths.filter((p) => !out.taken.includes(p) && out.merged[p] !== undefined);
  out.ok = !out.violations.length && !out.conflicts.length && !out.breaks.length;
  return out;
}

/** Config values: a scoped change may only change keys under its prefixes; every other key keeps ours. */
export function guardConfigValues(ours: Readonly<Record<string, unknown>>, theirs: Readonly<Record<string, unknown>>, plan: ScopedPlan): { values: Record<string, unknown>; refused: string[] } {
  if (plan.scope.kind === "whole") return { values: { ...theirs }, refused: [] };
  const values: Record<string, unknown> = { ...ours };
  const refused: string[] = [];
  for (const [k, v] of Object.entries(theirs)) {
    if (JSON.stringify(ours[k]) === JSON.stringify(v)) continue;
    if (plan.may.configPrefixes.some((p) => k.startsWith(p))) values[k] = v; else refused.push(k);
  }
  return { values, refused: refused.sort() };
}

// ------------------------------------------------------------------------------------------------ fingerprints + history
/** FNV-1a 64 over a string, hex (change detection only). */
export function fingerprint(s: string): string {
  let h = 0xcbf29ce484222325n;
  for (let i = 0; i < s.length; i++) { h ^= BigInt(s.charCodeAt(i)); h = (h * 0x100000001b3n) & 0xffffffffffffffffn; }
  return h.toString(16).padStart(16, "0");
}

/** One fingerprint per module: its definition + the content keys of every file it owns (designs, assets, own files). */
export function moduleFingerprints(spec: ModSpecV2, files: FileState, designs: readonly DesignRef[] = []): Record<string, string> {
  const out: Record<string, string> = {};
  const own = ownership(spec, designs);
  for (const m of spec.modules) {
    const plan = planScopedChange(spec, { kind: "module", id: m.id }, designs) as ScopedPlan;
    const mine = Object.keys(files).filter((p) => isSourceOfTruth(p) && pathInScope(plan, p)).sort().map((p) => `${p}=${files[p]}`);
    const slotSpecs = spec.assets.filter((a) => own.slot.get(a.id) === m.id).map((a) => JSON.stringify(a));
    out[m.id] = fingerprint(JSON.stringify({ m, mine, slotSpecs }));
  }
  return out;
}

/** What a revision records about its scope (engine.scope / engine.moduleHashes / engine.tokens). */
export type ScopeRecord = { scope?: Scope; moduleHashes?: Record<string, string>; tokens?: number };
export function validateScopeRecord(r: Record<string, unknown>): string[] {
  const out: string[] = [];
  if (r.scope !== undefined) {
    const s = r.scope as { kind?: unknown; id?: unknown };
    if (!s || typeof s !== "object" || !(s.kind === "whole" || (s.kind === "module" && typeof s.id === "string" && SLOT_ID_RE.test(s.id)))) out.push("scope: must be { kind: whole } or { kind: module, id }");
  }
  if (r.moduleHashes !== undefined) {
    const h = r.moduleHashes;
    if (!h || typeof h !== "object" || Array.isArray(h) || Object.keys(h).length > SUITE_LIMITS.maxModules || Object.entries(h).some(([k, v]) => !SLOT_ID_RE.test(k) || typeof v !== "string" || !/^[0-9a-f]{16,64}$/.test(v))) out.push("moduleHashes: module id -> hex fingerprint");
  }
  if (r.tokens !== undefined && !(Number.isInteger(r.tokens) && (r.tokens as number) >= 0 && (r.tokens as number) < 1e9)) out.push("tokens: a whole number >= 0");
  return out;
}

export type RevisionLite = { seq: number; status: "pending" | "passed" | "failed"; engine?: ScopeRecord | null };
export type ModuleStatus = {
  id: string;
  /** Part revision: 1 + how many times its fingerprint changed. */
  rev: number;
  lastChangedSeq: number | null;
  /** passed / failed = the newest finished flight covering it ran on its current content; stale = changed since. */
  flight: "passed" | "failed" | "stale" | "none";
  lastFlightSeq: number | null;
  tokens: number;
};
export type SuiteStatus = { modules: ModuleStatus[]; whole: { flight: "passed" | "failed" | "stale" | "none"; lastFlightSeq: number | null; tokens: number } };

/**
 * Per-module revisions, flights and spend, derived from the revision chain (oldest first). A module flight covers the
 * module and its dependency closure (it builds the module's export); a whole flight covers everything. Tokens go to the
 * revision's scope; whole-mod builds stay in the "whole mod" bucket (never split by guess).
 */
export function suiteStatus(spec: ModSpecV2, revisions: readonly RevisionLite[]): SuiteStatus {
  const revs = [...revisions].sort((a, b) => a.seq - b.seq);
  const st = new Map<string, ModuleStatus & { hash?: string; flightHash?: string }>(spec.modules.map((m) => [m.id, { id: m.id, rev: 0, lastChangedSeq: null, flight: "none", lastFlightSeq: null, tokens: 0 }]));
  const whole = { flight: "none" as SuiteStatus["whole"]["flight"], lastFlightSeq: null as number | null, tokens: 0, hashes: null as Record<string, string> | null };
  let current: Record<string, string> = {};
  for (const r of revs) {
    const e = r.engine ?? {};
    if (e.moduleHashes) {
      for (const [id, h] of Object.entries(e.moduleHashes)) { const s = st.get(id); if (s && s.hash !== h) { s.rev++; s.lastChangedSeq = r.seq; s.hash = h; } }
      current = { ...current, ...e.moduleHashes };
    }
    const scope = e.scope;
    if (scope?.kind === "module" && st.has(scope.id)) st.get(scope.id)!.tokens += e.tokens ?? 0; else whole.tokens += e.tokens ?? 0;
    if (r.status === "pending") continue;
    const covered = !scope || scope.kind === "whole" ? spec.modules.map((m) => m.id) : [scope.id, ...dependencyClosure(spec.modules, scope.id)];
    for (const id of covered) { const s = st.get(id); if (s) { s.flight = r.status; s.lastFlightSeq = r.seq; s.flightHash = current[id]; } }
    if (!scope || scope.kind === "whole") { whole.flight = r.status; whole.lastFlightSeq = r.seq; whole.hashes = { ...current }; }
  }
  for (const s of st.values()) { if (s.rev === 0) s.rev = 1; if (s.flight !== "none" && s.flightHash !== current[s.id]) s.flight = "stale"; }
  if (whole.hashes && Object.entries(current).some(([k, v]) => whole.hashes![k] !== v)) whole.flight = "stale";
  return { modules: spec.modules.map((m) => { const { hash: _h, flightHash: _f, ...rest } = st.get(m.id)!; return rest; }), whole: { flight: whole.flight, lastFlightSeq: whole.lastFlightSeq, tokens: whole.tokens } };
}

// ------------------------------------------------------------------------------------------------ export + generation
/** Rewrite every `<from>:` id prefix in a JSON value to `<to>:`. */
export function renamespace<T>(x: T, from: string, to: string): T {
  const re = new RegExp(`^${from}:`);
  const walk = (v: unknown): unknown => typeof v === "string" ? v.replace(re, `${to}:`) : Array.isArray(v) ? v.map(walk) : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, y]) => [k, walk(y)])) : v;
  return walk(x) as T;
}

/**
 * Export a module as its own mod: the module + its dependency closure, the assets/designs/requirements/tests they own,
 * under a NEW namespace (ids rewritten). Also what a module-level Test Flight builds.
 */
export function exportModule(spec: ModSpecV2, id: string, newNamespace: string, designs: readonly DesignRef[] = []): { ok: true; spec: ModSpecV2; designs: DesignRef[]; modules: string[] } | { ok: false; error: string } {
  if (!spec.modules.some((m) => m.id === id)) return { ok: false, error: `no module ${id}` };
  if (!NAMESPACE_RE.test(newNamespace)) return { ok: false, error: "the new mod needs its own reserved nx_ namespace" };
  const keep = new Set([id, ...dependencyClosure(spec.modules, id)]);
  const own = ownership(spec, designs);
  const modules = spec.modules.filter((m) => keep.has(m.id)).map((m) => ({ ...m, default: m.id === id ? true : m.default && false, dependsOn: m.dependsOn.filter((d) => keep.has(d)) }));
  modules.forEach((m) => { if (m.default === false) delete (m as { default?: boolean }).default; });
  const assets = spec.assets.filter((a) => keep.has(own.slot.get(a.id) ?? ""));
  const reqIds = new Set(modules.flatMap((m) => m.requirementIds));
  const requirements = spec.requirements.filter((r) => reqIds.has(r.id));
  const fallbackReq = requirements.length ? requirements : [{ id: "REQ-1", text: `Everything in ${id}`, priority: "must" as const }];
  const out: ModSpecV2 = renamespace({
    ...spec, namespace: newNamespace, modules,
    assets: assets.map((a) => ({ ...a, requirementIds: a.requirementIds.filter((r) => reqIds.has(r)) })),
    requirements: fallbackReq, tests: spec.tests.filter((t) => t.covers.every((c) => reqIds.has(c))),
  }, spec.namespace, newNamespace);
  out.namespace = newNamespace;
  const ds = designs.filter((d) => keep.has(own.design.get(d.id) ?? "")).map((d) => ({ ...d, json: renamespace(d.json, spec.namespace, newNamespace) }));
  return { ok: true, spec: out, designs: ds, modules: modules.map((m) => m.id) };
}

export type GenerationStep = { module: string; kind: ModuleKind; after: string[]; interfaces: { module: string; provides: string[] }[]; requirements: string[]; contextChars: number };
/**
 * Decomposed generation: modules in dependency order; each step sees only its own requirements and the INTERFACES of
 * its dependencies (not their designs), so the model context stays small however big the mod is.
 */
export function planSuiteGeneration(spec: ModSpecV2, designs: readonly DesignRef[] = []): { ok: true; steps: GenerationStep[]; wholeContextChars: number } | { ok: false; error: string } {
  const cyc = findCycle(spec.modules);
  if (cyc) return { ok: false, error: `dependency cycle: ${cyc.join(" -> ")}` };
  const done = new Set<string>();
  const steps: GenerationStep[] = [];
  const left = [...spec.modules];
  while (left.length) {
    const i = left.findIndex((m) => m.dependsOn.every((d) => done.has(d) || !spec.modules.some((x) => x.id === d)));
    const m = left.splice(i < 0 ? 0 : i, 1)[0];
    const p = planScopedChange(spec, { kind: "module", id: m.id }, designs) as ScopedPlan;
    steps.push({ module: m.id, kind: m.kind, after: [...m.dependsOn], interfaces: p.interfaces.map((x) => ({ module: x.module, provides: x.provides })), requirements: p.requirements.map((r) => r.id), contextChars: p.contextChars });
    done.add(m.id);
  }
  return { ok: true, steps, wholeContextChars: JSON.stringify({ spec, designs: designs.map((d) => d.json) }).length };
}

// ------------------------------------------------------------------------------------------------ size budget
export type BudgetLine = { id: string; label: string; value: number; max: number; level: "ok" | "warn" | "over"; measured: boolean; note?: string };
/**
 * Honest size budget of a suite from its design files. `measured: true` lines carry thresholds that a real Test Flight
 * of a large synthetic suite backed (see SUITE_MEASURED); the rest are estimates and say so.
 */
export function suiteBudget(designs: readonly DesignRef[], limits: { maxDesignFiles: number }, measured: { designFiles?: number; periodicPerSecond?: number } = {}): BudgetLine[] {
  let periodic = 0;
  const triggers = new Set<string>();
  for (const d of designs) {
    if (d.kind !== "item" || !d.json || typeof d.json !== "object") continue;
    for (const ab of ((d.json as { abilities?: { trigger?: { type?: string; periodTicks?: number } }[] }).abilities ?? [])) {
      const t = ab.trigger?.type; if (t) triggers.add(t);
      if (t === "held_interval" && ab.trigger?.periodTicks) periodic += 20 / ab.trigger.periodTicks;
    }
  }
  const line = (id: string, label: string, value: number, max: number, isMeasured: boolean, note?: string): BudgetLine => ({ id, label, value: Math.round(value * 100) / 100, max, level: value > max ? "over" : value > max * 0.75 ? "warn" : "ok", measured: isMeasured, ...(note ? { note } : {}) });
  return [
    line("design_files", "Design files", designs.length, limits.maxDesignFiles, measured.designFiles !== undefined && designs.length <= measured.designFiles, measured.designFiles !== undefined ? `a real Test Flight booted ${measured.designFiles} design files` : "estimate"),
    line("periodic", "Repeating abilities per player per second", periodic, 40, measured.periodicPerSecond !== undefined && periodic <= measured.periodicPerSecond, "held_interval abilities run every period for every player holding the item"),
    line("listeners", "Event triggers in use", triggers.size, 10, true, "the plugin registers one listener per trigger type, however many items use it"),
  ];
}

