const NS = "nx_4f2a91c0";
const v1 = {
  schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: NS, summary: "Moth King saga: weapons, moths, a quest line and a boss",
  routes: ["plugin"], requirements: [{ id: "REQ-1", text: "frost weapons" }, { id: "REQ-2", text: "moth creatures" }, { id: "REQ-3", text: "the moth pact quest" }],
  assets: [{ id: "frost_blade_tex", kind: "texture", purpose: "frost blade look", requirementIds: ["REQ-1"] }, { id: "moth_hurt", kind: "sound", purpose: "moth hurt sound", requirementIds: ["REQ-2"] }],
  install: { side: "server", restartRequired: true },
};
const designs: DesignRef[] = [
  { id: "frost_blade", kind: "item", json: { id: "frost_blade", name: "Frost Blade" } },
  { id: "frost_lantern", kind: "item", json: { id: "frost_lantern" } },
  { id: "moth_king", kind: "boss", json: { id: "moth_king", drops: [{ item: `${NS}:frost_lantern` }], sound: `${NS}:moth_hurt.hurt` } },
  { id: "moth_pact", kind: "quest", json: { id: "moth_pact", steps: [{ objective: { item: `${NS}:frost_blade` } }, { kill: `${NS}:moth_king` }] } },
];
function suite(over: Partial<ModSpecV2> = {}): ModSpecV2 {
  const r = validateModSpecV2({
    ...v1, schemaVersion: 2,
    modules: [
      { id: "weapons", kind: "items", title: "Frost weapons", requirementIds: ["REQ-1"], assets: ["frost_blade_tex"], designs: ["frost_blade", "frost_lantern"] },
      { id: "moths", kind: "creatures", title: "Moth creatures", requirementIds: ["REQ-2"], assets: ["moth_hurt"], designs: ["moth_king"], dependsOn: ["weapons"], provides: ["entity:moth"] },
      { id: "pact", kind: "quests", title: "The Moth Pact", requirementIds: ["REQ-3"], designs: ["moth_pact"], dependsOn: ["weapons", "moths"], uses: ["entity:moth"] },
    ],
    ...over,
  }, { adapterFor: getAdapter, designs });
  assert.ok(r.ok, JSON.stringify(!r.ok && r.errors));
  return r.spec;
}

describe("ModSpec v2: migration + validation", () => {
  it("a v1 spec becomes one default module, losslessly", () => {
    const r = validateModSpecV2(v1, { adapterFor: getAdapter });
    assert.ok(r.ok);
    assert.equal(r.migratedFrom, 1);
    assert.equal(r.spec.modules.length, 1);
    assert.equal(r.spec.modules[0].default, true);
    assert.deepEqual(r.spec.modules[0].requirementIds, ["REQ-1", "REQ-2", "REQ-3"]);
    const back = toV1(r.spec);
    assert.equal(back.schemaVersion, 1);
    assert.equal("modules" in back, false);
    assert.equal(migrateV1ToV2(v1).schemaVersion, 1, "the migration itself leaves the version to migrateSpec");
  });
  it("a proper suite validates with design cross-references", () => { const s = suite(); assert.equal(s.modules.length, 3); });
  it("dangling ids, self-dependency, cycles, double ownership and a missing dependency are errors", () => {
    const bad = validateModSpecV2({
      ...v1, schemaVersion: 2,
      modules: [
        { id: "a", kind: "items", title: "A", dependsOn: ["b", "ghost", "a"], assets: ["frost_blade_tex", "nope"], designs: ["frost_blade"], requirementIds: ["REQ-9"] },
        { id: "b", kind: "bosses", title: "B", dependsOn: ["a"], assets: ["frost_blade_tex"], designs: ["frost_blade", "moth_king"], uses: ["item:unknown_thing"] },
        { id: "c", kind: "quests", title: "C", designs: ["moth_pact", "frost_lantern"] },
      ],
    }, { adapterFor: getAdapter, designs });
    assert.equal(bad.ok, false);
    const codes = new Set(!bad.ok ? bad.errors.map((e) => e.code) : []);
    for (const c of ["dangling_dependency", "self_dependency", "dependency_cycle", "dangling_asset", "asset_in_two_modules", "design_in_two_modules", "unknown_requirement", "dangling_reference", "missing_dependency"]) assert.ok(codes.has(c), c);
  });
  it("a reference inside a design to another module needs the dependency", () => {
    const s = suite();
    const noDep = { ...s, modules: s.modules.map((m) => (m.id === "pact" ? { ...m, dependsOn: ["moths"] } : m)) };
    // moths depends on weapons, so pact -> moths -> weapons is still a closure: fine
    assert.equal(validateModules(noDep, designs).errors.length, 0);
    const cut = { ...s, modules: s.modules.map((m) => (m.id === "pact" ? { ...m, dependsOn: [] as string[], uses: [] as string[] } : m.id === "moths" ? { ...m, dependsOn: [] as string[] } : m)) };
    const e = validateModules(cut, designs).errors;
    assert.ok(e.some((x) => x.code === "missing_dependency" && x.message.includes("moth_pact")), JSON.stringify(e));
    assert.ok(e.some((x) => x.message.includes("frost_lantern")), "the boss drop needs weapons");
  });
  it("cycle path and closure", () => {
    assert.deepEqual(findCycle([{ id: "a", dependsOn: ["b"] }, { id: "b", dependsOn: ["c"] }, { id: "c", dependsOn: ["a"] }]), ["a", "b", "c", "a"]);
    assert.deepEqual(dependencyClosure(suite().modules, "pact"), ["moths", "weapons"]);
    assert.deepEqual(designReferences(designs[3].json, NS), ["frost_blade", "moth_king"]);
  });
  it("the engine record takes scope, module fingerprints and tokens", () => {
    assert.ok(validateEngineRecord({ scope: { kind: "module", id: "pact" }, moduleHashes: { pact: "0123456789abcdef" }, tokens: 1820 }).ok);
    assert.equal(validateEngineRecord({ scope: { kind: "module", id: "Bad Id" } }).ok, false);
    assert.equal(validateEngineRecord({ tokens: -1 }).ok, false);
  });
});

describe("scoped change", () => {
  const s = suite();
  const plan = planScopedChange(s, { kind: "module", id: "pact" }, designs) as ScopedPlan;
  it("a part sees its own designs and only the interfaces of its dependencies", () => {
    assert.deepEqual(plan.may.designs, ["moth_pact"]);
    assert.deepEqual(plan.may.configPrefixes, ["quests.moth_pact."]);
    assert.deepEqual(plan.interfaces.map((i) => i.module), ["moths", "weapons"]);
    assert.ok(plan.interfaces.find((i) => i.module === "weapons")!.provides.includes("item:frost_blade"));
    const whole = planScopedChange(s, { kind: "whole" }, designs) as ScopedPlan;
    assert.ok(plan.contextChars < whole.contextChars, "scoped context is smaller than the whole mod");
    const w = planScopedChange(s, { kind: "module", id: "weapons" }, designs) as ScopedPlan;
    assert.deepEqual(w.dependents.map((d) => d.module).sort(), ["moths", "pact"]);
    assert.ok(w.dependents.find((d) => d.module === "pact")!.uses.includes("frost_blade"));
  });
  it("the three-way guard takes in-scope changes, keeps the rest, reports conflicts and breaks", () => {
    const base = { "assets/designs/moth_pact.json": "q1", "assets/designs/frost_blade.json": "b1", "assets/designs/moth_king.json": "k1", "src/main/java/x/Main.java": "j1" };
    const ours = { ...base, "assets/designs/moth_king.json": "k2" };
    const theirs = { ...base, "assets/designs/moth_pact.json": "q2", "assets/designs/frost_blade.json": "b9", "src/main/java/x/Main.java": "j2" };
    const g = guardScopedResult(base, ours, theirs, plan);
    assert.equal(g.merged["assets/designs/moth_pact.json"], "q2");
    assert.equal(g.merged["assets/designs/frost_blade.json"], "b1", "outside the scope: ours wins");
    assert.equal(g.merged["assets/designs/moth_king.json"], "k2", "a manual edit elsewhere is kept");
    assert.deepEqual(g.violations, ["assets/designs/frost_blade.json"]);
    assert.equal(g.ok, false);
    const c = guardScopedResult(base, { ...base, "assets/designs/moth_pact.json": "q-hand" }, { ...base, "assets/designs/moth_pact.json": "q2" }, plan);
    assert.deepEqual(c.conflicts, ["assets/designs/moth_pact.json"]);
    assert.equal(c.merged["assets/designs/moth_pact.json"], "q-hand");
    const w = planScopedChange(s, { kind: "module", id: "weapons" }, designs) as ScopedPlan;
    const br = guardScopedResult(base, base, base, w, { before: ["item:frost_blade", "item:frost_lantern"], after: ["item:frost_lantern"] });
    assert.ok(br.breaks.some((b) => b.dependent === "pact" && b.provide === "item:frost_blade"));
  });
  it("config values outside the scope are refused", () => {
    const r = guardConfigValues({ "quests.moth_pact.reward": 1, "items.frost_blade.damage": 6 }, { "quests.moth_pact.reward": 5, "items.frost_blade.damage": 40 }, plan);
    assert.equal(r.values["quests.moth_pact.reward"], 5);
    assert.equal(r.values["items.frost_blade.damage"], 6);
    assert.deepEqual(r.refused, ["items.frost_blade.damage"]);
  });
});

describe("per-module revisions, flights and spend", () => {
  const s = suite();
  const f0 = { "assets/designs/frost_blade.json": "b1", "assets/designs/moth_pact.json": "q1", "assets/designs/moth_king.json": "k1" };
  const h0 = moduleFingerprints(s, f0, designs);
  const h1 = moduleFingerprints(s, { ...f0, "assets/designs/moth_pact.json": "q2" }, designs);
  it("fingerprints change only for the edited module", () => {
    assert.notEqual(h0.pact, h1.pact);
    assert.equal(h0.weapons, h1.weapons);
    assert.equal(h0.moths, h1.moths);
  });
  it("status: revisions per part, flights cover closures, stale after a change, spend by scope", () => {
    const st = suiteStatus(s, [
      { seq: 1, status: "passed", engine: { scope: { kind: "whole" }, moduleHashes: h0, tokens: 5000 } },
      { seq: 2, status: "passed", engine: { scope: { kind: "module", id: "pact" }, moduleHashes: h1, tokens: 800 } },
      { seq: 3, status: "pending", engine: { scope: { kind: "module", id: "weapons" }, moduleHashes: { ...h1, weapons: "ffffffffffffffff" }, tokens: 300 } },
    ]);
    const by = Object.fromEntries(st.modules.map((m) => [m.id, m]));
    assert.equal(by.pact.rev, 2);
    assert.equal(by.pact.flight, "passed");
    assert.equal(by.pact.tokens, 800);
    assert.equal(by.weapons.rev, 2);
    assert.equal(by.weapons.flight, "stale", "changed in rev 3, not flown since");
    assert.equal(by.weapons.tokens, 300);
    assert.equal(by.moths.flight, "passed", "covered by pact's flight (its dependency)");
    assert.equal(st.whole.tokens, 5000);
    assert.equal(st.whole.flight, "stale");
  });
});

