  const s = suite();
  it("a module exports with its closure under a new namespace", () => {
    const r = exportModule(s, "pact", "nx_99990000", designs);
    assert.ok(r.ok);
    assert.deepEqual(r.modules.sort(), ["moths", "pact", "weapons"]);
    assert.equal(r.spec.namespace, "nx_99990000");
    assert.ok(JSON.stringify(r.designs).includes("nx_99990000:frost_blade"));
    assert.ok(!JSON.stringify(r.designs).includes(NS));
    const w = exportModule(s, "weapons", "nx_99990001", designs);
    assert.ok(w.ok);
    assert.deepEqual(w.modules, ["weapons"]);
    assert.deepEqual(w.designs.map((d) => d.id).sort(), ["frost_blade", "frost_lantern"]);
    assert.ok(validateModSpecV2(w.spec, { adapterFor: getAdapter, designs: w.designs }).ok);
  });
  it("generation runs in dependency order with small per-step context", () => {
    const g = planSuiteGeneration(s, designs);
    assert.ok(g.ok);
    assert.deepEqual(g.steps.map((x) => x.module), ["weapons", "moths", "pact"]);
    assert.ok(g.steps.every((x) => x.contextChars < g.wholeContextChars));
