});

describe("designer suite limits", () => {
  const item = (i: number) => ({ id: `blade_${i}`, name: `Blade ${i}`, base: "iron_sword", abilities: [] });
  it("default limits are unchanged; suite limits allow more items", () => {
    const many = Array.from({ length: 10 }, (_, i) => item(i + 1));
    const d = validateGameplay(many, { version: "1.21.11", namespace: NS });
    assert.ok(d.errors.some((e) => e.code === "too_many_items"), "6 items is today's per-mod limit");
