// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.
import type { PlaytestPlan } from "../playtest/plan";

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "playtest", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type SeedRef = { from: string; to: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  /**
   * Read-only directories prepared on node-2 under `<root>/seeds/<from>` copied into the server dir before boot
   * (`to` = "libraries" or a path under plugins/). The flight has no internet, so a managed plugin's pinned runtime
   * libraries are seeded this way (runner tf-lite-2).
   */
  seeds?: SeedRef[];
  /** Server-dir files copied out after the stop to `<root>/collect/<runId>/` (a path ending in "/" = a listing). */
  collect?: string[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
  /** World options (runner tf-lite-3): generateStructures turns structure generation on (default off: a tiny flat world). */
  world?: { generateStructures?: boolean };
  /** Playtest (runner tf-lite-4): a scripted Mineflayer player runs these scenarios after the RCON checks. Makes `playtest` required. */
  playtest?: PlaytestPlan;
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];

