// v8 mod suites: a LARGE SYNTHETIC suite for the size budget (unit test + test/cyrus-suite-real.ts). It copies the
// verified designer fixtures (items, menus + quests, bosses + encounters) `copies` times, each copy one group of three
// modules (weapons_<k>, guild_<k> -> weapons_<k>, trials_<k> -> weapons_<k>), every id suffixed and every namespace
// rewritten into ONE namespace. No AI model: designs are fixtures.
import { readFileSync } from "node:fs";
import path from "node:path";
import { GAMEPLAY_FIXTURES } from "./gameplay-golden";
import { BOSS_FIXTURES } from "./boss-golden";

export const SUITE_NS = "nx_v8suite1";
export const SUITE_PLUGIN = "SagaSuite";
const FX = path.join(__dirname, "../../test/fixtures");
const load = (dir: string, n: string) => JSON.parse(readFileSync(path.join(FX, dir, `${n}.json`), "utf8")) as Record<string, unknown>;
const ITEMS = ["void_reaper", "storm_staff", "vigor_tonic"];

/** Rename every design id of a group (exact strings and `<ns>:<id>...`) and move every namespace to SUITE_NS. */
function rename<T>(x: T, ids: ReadonlySet<string>, k: number): T {
  const walk = (v: unknown): unknown => {
    if (typeof v === "string") {
      if (ids.has(v)) return `${v}_${k}`;
      const m = /^nx_[a-z0-9]+:([a-z][a-z0-9_]*)(.*)$/.exec(v);
      if (m) return `${SUITE_NS}:${ids.has(m[1]) ? `${m[1]}_${k}` : m[1]}${m[2]}`;
      return v;
    }
    if (Array.isArray(v)) return v.map(walk);
    if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([a, b]) => [a, walk(b)]));
    return v;
  };
  return walk(x) as T;
}

export type SyntheticSuite = { designs: Record<string, unknown>[]; modules: { id: string; kind: string; title: string; designs: string[]; dependsOn: string[] }[] };

export function syntheticSuite(copies: number): SyntheticSuite {
  const designs: Record<string, unknown>[] = [];
  const modules: SyntheticSuite["modules"] = [];
  for (let k = 1; k <= copies; k++) {
    const groups: [string, string, string, string[], Record<string, unknown>[]][] = [
      [`weapons_${k}`, "items", `Weapons ${k}`, [], ITEMS.map((n) => load("cyrus-designer", n))],
      [`guild_${k}`, "quests", `Guild ${k}`, [], GAMEPLAY_FIXTURES.map((n) => load("cyrus-gameplay", n))],
      [`trials_${k}`, "bosses", `Trials ${k}`, [], BOSS_FIXTURES.map((n) => load("cyrus-boss", n))],
    ];
    for (const [id, kind, title, deps, ds] of groups) {
      const ids = new Set(ds.map((d) => String(d.id)));
      const renamed = ds.map((d) => rename(d, ids, k));
      designs.push(...renamed);
      modules.push({ id, kind, title, designs: renamed.map((d) => String(d.id)), dependsOn: deps });
    }
  }
  return { designs, modules };
}

