// REAL v8 mod-suite size run ON node-2 (not in the unit suite: real javac, strict scan, real Paper boots via Test Flight).
//   scripts/devhost run --lock -- npx tsx test/cyrus-suite-real.ts --out /tank/nxeon-build/tmp/cyrus-r45-suite/results.json
// Two flights on Paper 1.21.11, one at a time: a SMALL suite (1 copy of the designer fixtures, 17 design files) and a
// LARGE synthetic suite (4 copies + 4 item modules, 80 design files, 44 items, 8 bosses, 4 encounters) under
// SUITE_KIND_LIMITS. Measures compile, javac, jar size, boot time, peak RSS and Paper's MSPT; checks every boss of every
// module is registered and that a boss from the last copy spawns. No AI model, no client, no bot.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { SUITE_KIND_LIMITS } from "../lib/cyrus/designer/gameplay/spec";
import { validateModSpecV2, suiteBudget, planSuiteGeneration } from "../lib/cyrus/engine-core/modules";
import { getAdapter } from "../lib/cyrus/adapters";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";
import { syntheticSuite, SUITE_NS as NS, SUITE_PLUGIN as PLUGIN } from "../scripts/cyrus/suite-synthetic";

const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r45-suite/run-${Date.now().toString(36)}`;
const LANE = { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` };
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const CMD = PLUGIN.toLowerCase();

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}
function build(r: ModCompileOk, tag: string) {
  const dir = path.join(RUN, tag);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(LANE.cp, "utf8").replace(/\n/g, "").trim();
  const t0 = Date.now();
  let out = "";
  try { out = execFileSync(`${LANE.jdk}/bin/javac`, ["-J-Xmx768m", "--release", LANE.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 12000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, `${PLUGIN}-${tag}.jar`);
  execFileSync(`${LANE.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  const S = require(path.resolve(__dirname, "../services/modbuilder/scan.js"));
  const oldPath = process.env.PATH; process.env.PATH = `${LANE.jdk}/bin:${oldPath}`;
  let scan: { blocks: number; warnings: number };
  try { const all = [...S.scanBytecode(classes, { profile: "strict" }), ...S.scanSource(walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(dir, "ws"), abs) })), { profile: "strict" })]; scan = { blocks: all.filter((f: { severity: string }) => f.severity === "block").length, warnings: all.filter((f: { severity: string }) => f.severity === "warn").length }; }
  finally { process.env.PATH = oldPath; }
  return { sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (out.match(/warning:/g) ?? []).length, jarPath, jarSha256: sha(readFileSync(jarPath)), jarBytes: readFileSync(jarPath).length, scan };
}

async function lane(label: string, copies: number, extra: number) {
  const s = syntheticSuite(copies, extra);
  const L: Record<string, unknown> = { label, copies, extraWeapons: extra, designFiles: s.designs.length, modules: s.modules.length };
  // the suite as a ModSpec v2: modules validate with their cross-references
  const spec = validateModSpecV2({ schemaVersion: 2, game: "minecraft", target: { version: LANE.version }, namespace: NS, summary: `Synthetic suite ${label} for the size budget`, routes: ["plugin"], requirements: [{ id: "REQ-1", text: "everything boots" }], install: { side: "server", restartRequired: true }, modules: s.modules }, { adapterFor: getAdapter, designs: s.designs.map((d) => ({ id: String(d.id), kind: String(d.kind ?? "item"), json: d })) });
  L.spec = spec.ok ? { ok: true, warnings: spec.warnings.map((w) => w.code) } : { ok: false, errors: spec.errors.slice(0, 8) };
  const gen = spec.ok ? planSuiteGeneration(spec.spec, s.designs.map((d) => ({ id: String(d.id), kind: String(d.kind ?? "item"), json: d }))) : null;
  if (gen?.ok) L.generation = { steps: gen.steps.length, maxStepContextChars: Math.max(...gen.steps.map((x) => x.contextChars)), wholeContextChars: gen.wholeContextChars };
  L.budget = suiteBudget(s.designs.map((d) => ({ id: String(d.id), kind: String(d.kind ?? "item"), json: d })), SUITE_KIND_LIMITS);
  const t0 = Date.now();
  const c = compileMod(s.designs, { version: LANE.version, namespace: NS, pluginName: PLUGIN, limits: SUITE_KIND_LIMITS });
  if (!c.ok) { L.compile = { ok: false, errors: c.errors.slice(0, 8) }; return L; }
  L.compile = { ok: true, ms: Date.now() - t0, files: c.files.length, params: c.params.length, counts: c.counts, bosses: c.bosses.length, encounters: c.encounters.length };
  const b = build(c, label);
  L.javac = { sources: b.sources, classFiles: b.classFiles, ms: b.javacMs, warnings: b.javacWarnings };
  L.jar = { bytes: b.jarBytes, sha256: b.jarSha256 };
  L.scan = b.scan;
  const bosses = c.bosses.map((x) => x.id);
  const last = bosses.filter((x) => x.startsWith("grave_lord")).sort().at(-1)!;
  const rcon: RconCheck[] = [
    { id: "plugins", command: "plugins", expect: [PLUGIN] },
    { id: "boss-list", command: `${CMD} boss list`, expect: bosses.map((x) => `${x}: entity=`), expectNot: ["Exception", "internal error"] },
    { id: "encounter-list", command: `${CMD} encounter list`, expect: c.encounters.map((x) => `${x.id}: waves=`) },
    { id: "params-last", command: `${CMD} params ${last}`, expect: [`bosses.${last}.stats.health=`] },
    { id: "difficulty", command: "difficulty easy", expect: ["The difficulty has been set to Easy"] },
    { id: "forceload", command: "forceload add ~-32 ~-32 ~48 ~32", expect: ["chunks"] },
    { id: "spawn-last", command: `${CMD} boss spawn ${last} spawn`, expect: [`Spawned ${last}#1`] },
    { id: "mspt-loaded", waitMs: 5000, command: "mspt", expect: [], required: false },
    { id: "despawn", command: `${CMD} boss despawn all`, expect: ["Despawned 1 bosses."] },
    { id: "reload", command: `${CMD} reload`, expect: ["reloaded"], expectNot: ["Exception"] },
    { id: "mspt-idle", waitMs: 5000, command: "mspt", expect: [], required: false },
  ];
  const f = await fly({ version: LANE.version, plugins: [{ localPath: b.jarPath, sha256: b.jarSha256 }], rcon }, `flight ${label}`);
  const ev = f.report.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [];
  L.flight = { status: f.report.status, success: f.summary.success, line: describeSummary(f.summary), bootMs: f.report.bootMs, peakRssMb: f.report.peakRssKb ? Math.round(f.report.peakRssKb / 1024) : null, paper: f.report.engine?.paper ?? null, checks: f.report.checks.map((x) => ({ id: x.id, status: x.status })), mspt: ev.filter((x) => x.startsWith("mspt")).map((x) => x.slice(0, 300)), failures: f.report.checks.filter((x) => x.status !== "pass").map((x) => ({ id: x.id, evidence: x.evidence.slice(0, 12) })) };
  console.log(`${label}: ${describeSummary(f.summary)} boot=${f.report.bootMs}ms rss=${(L.flight as { peakRssMb: number }).peakRssMb}MB`);
  return L;
}

async function main() {
  mkdirSync(RUN, { recursive: true });
  const res: Record<string, unknown> = { what: "Cyrus r45 v8 mod suites: synthetic suite size run (Test Flight, Paper 1.21.11)", at: new Date().toISOString(), host: "node-2", aiModel: "none (fixtures)", realClient: false, lanes: [] as unknown[] };
  (res.lanes as unknown[]).push(await lane("small", 1, 0));
  (res.lanes as unknown[]).push(await lane("large", 4, 4));
  const out = arg("--out");
  if (out) { mkdirSync(path.dirname(out), { recursive: true }); writeFileSync(out, JSON.stringify(res, null, 1)); console.log(`wrote ${out}`); }
  else console.log(JSON.stringify(res, null, 1));
  rmSync(RUN, { recursive: true, force: true });
}
main().catch((e) => { console.error(e); process.exit(1); });

