"use client";
// v8 structure: a selected mod opens into its PARTS (items, quests, textures, config...) as a second fan beyond the mod
// pill, in the map's own pill language. Lives inside the world layer, so it pans and zooms with the graph; Network moves
// its anchor every frame (setFanAnchor). Click a part: its studio opens scoped to that part. Phones: the same parts as a
// list under the pill (CSS). Data: lib/cyrus/structure/parts.ts (derived from the build, or the suite's modules).
import { forwardRef, type PointerEvent as RPointerEvent } from "react";
import { partHref, type Part } from "@/lib/cyrus/structure/parts";
import type { ModuleKind } from "@/lib/cyrus/engine-core/modules";
import "./partfan.css";

export const PART_ICON: Record<ModuleKind, string> = {
  items: "M4 18l9-9m0 0 3-3 2 2-3 3m-2-2 2 2M6 14l4 4",
  creatures: "M7 10a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm10 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM6 17c2-4 10-4 12 0",
  quests: "M7 4h9l2 2v14H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm2 5h6M9 13h6",
  menus: "M5 5h6v6H5zM13 5h6v6h-6zM5 13h6v6H5zM13 13h6v6h-6z",
  bosses: "M4 17l2-9 4 4 2-6 2 6 4-4 2 9Z",
  hud: "M4 8h16v8H4zM7 12h6",
  textures: "M4 5h16v14H4zM4 15l5-5 4 4 3-3 4 4",
  sounds: "M3 12h2l2-5 3 10 3-8 2 3h6",
  models: "M12 3l8 4.5v9L12 21l-8-4.5v-9Zm0 0v18M4 7.5l8 4.5 8-4.5",
  motions: "M8 5v14l11-7Z",
  config: "M12 14a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm-7 4a8 8 0 1 1 14 0",
  datapack: "M4 7l8-4 8 4-8 4Zm0 5 8 4 8-4M4 17l8 4 8-4",
  worldgen: "M3 18l6-9 4 6 3-4 5 7Z",
  code: "M9 7l-5 5 5 5M15 7l5 5-5 5",
};

export function PartIcon({ kind, className }: { kind: ModuleKind; className?: string }) {
  return <svg viewBox="0 0 24 24" className={className} fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d={PART_ICON[kind]} /></svg>;
}

const ROW = 40;
/** Where part `i` of `n` sits, relative to the fan origin, fanning toward `dir` (+1 right, -1 left). */
export function partSpot(i: number, n: number, dir: 1 | -1, vertical: 0 | 1 | -1 = 0) {
  const t = (i - (n - 1) / 2) / ((n - 1) / 2 + 0.6 || 1);
  const bulge = 40 + 70 * Math.sqrt(Math.max(0, 1 - t * t));
  if (vertical) return { x: (i - (n - 1) / 2) * 150, y: vertical * bulge };
  return { x: dir * bulge, y: (i - (n - 1) / 2) * ROW };
}

const DOT: Record<string, string> = { passed: "ok", failed: "bad", stale: "warn", none: "none" };

export const PartFan = forwardRef<HTMLDivElement, { buildId: string; modName: string; parts: Part[]; dir: 1 | -1; vertical?: 0 | 1 | -1; rgb: string; studios?: Partial<Record<string, boolean>>; current?: string | null }>(function PartFan({ buildId, modName, parts, dir, vertical = 0, rgb, studios, current }, ref) {
  const n = parts.length;
  const stop = (e: RPointerEvent) => e.stopPropagation();
  return (
    <div ref={ref} className="pf" style={{ ["--c" as string]: rgb }} data-dir={dir} data-vertical={vertical || undefined} onPointerDown={stop} aria-label={`Parts of ${modName}`} role="group">
      <svg className="pf-links" aria-hidden width="1" height="1">
        {parts.map((p, i) => {
          const s = partSpot(i, n, dir, vertical);
          const d = vertical ? `M0 0 C 0 ${s.y * 0.5}, ${s.x} ${s.y * 0.5}, ${s.x} ${s.y}` : `M0 0 C ${dir * 30} 0, ${s.x - dir * 34} ${s.y}, ${s.x} ${s.y}`;
          return <path key={p.id} d={d} className={p.id === current ? "on" : ""} />;
        })}
      </svg>
      {parts.map((p, i) => {
        const s = partSpot(i, n, dir, vertical);
        const href = partHref(buildId, p, studios);
        const body = (
          <>
            <span className="pf-ico"><PartIcon kind={p.kind} /></span>
            <span className="pf-t"><b>{p.label}</b><small>{p.detail}</small></span>
            {p.status ? <i className={`pf-dot ${DOT[p.status] ?? "none"}`} title={`Test Flight: ${p.status}`} /> : null}
          </>
        );
        const style = { transform: `translate(${s.x}px, ${s.y}px)` };
        return href ? (
          <a key={p.id} className={`pf-part${p.id === current ? " on" : ""}`} data-side={dir > 0 ? "right" : "left"} href={href} style={style} title={`Open ${p.label}`}>{body}</a>
        ) : (
          <span key={p.id} className="pf-part off" data-side={dir > 0 ? "right" : "left"} style={style} title="This studio is not switched on here">{body}</span>
        );
      })}
    </div>
  );
});

