/* v8: the parts fan of a selected mod (components/cyrus/cosmos/PartFan.tsx). Same anatomy as the mod pills. */
.cyrus-root .pf { position: absolute; left: 0; top: 0; width: 0; height: 0; z-index: 3; will-change: transform; animation: pf-in 0.35s cubic-bezier(.2, .8, .2, 1) both; }
@keyframes pf-in { from { opacity: 0; } to { opacity: 1; } }
.cyrus-root .pf-links { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; }
.cyrus-root .pf-links path { fill: none; stroke: rgb(var(--c) / 0.42); stroke-width: 1.2; }
.cyrus-root .pf-links path.on { stroke: rgb(var(--c)); stroke-width: 2; filter: drop-shadow(0 0 4px rgb(var(--c) / 0.8)); }
.cyrus-root .pf-part {
  position: absolute; left: 0; top: 0; display: flex; align-items: center; gap: 8px; height: 32px; min-width: 150px; max-width: 220px;
  padding: 0 10px 0 5px; border-radius: 10px; background: rgb(8 9 28 / 0.9); border: 1px solid rgb(var(--c) / 0.3);
  color: var(--ink-2); font-size: 12px; text-decoration: none; white-space: nowrap; translate: 0 -50%;
  transition: border-color 0.2s, box-shadow 0.2s, color 0.2s, background-color 0.2s;
}
.cyrus-root .pf-part[data-side="left"] { translate: -100% -50%; flex-direction: row-reverse; padding: 0 5px 0 10px; text-align: right; }
.cyrus-root .pf[data-vertical] .pf-part { translate: -50% -50%; }
.cyrus-root .pf-part:hover, .cyrus-root .pf-part:focus-visible { color: var(--ink); border-color: rgb(var(--c) / 0.8); box-shadow: 0 0 14px rgb(var(--c) / 0.35); outline: none; }
.cyrus-root .pf-part.on { color: #fff; background: rgb(var(--c) / 0.16); border-color: rgb(var(--c)); box-shadow: 0 0 0 1px rgb(var(--c) / 0.4), 0 0 18px rgb(var(--c) / 0.5); }
.cyrus-root .pf-part.off { opacity: 0.55; cursor: default; }
.cyrus-root .pf-ico { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 7px; background: rgb(var(--c) / 0.1); color: rgb(var(--c)); flex: none; }
.cyrus-root .pf-ico svg { width: 14px; height: 14px; }
.cyrus-root .pf-t { display: grid; line-height: 1.15; min-width: 0; }
.cyrus-root .pf-t b { font-weight: 600; color: var(--ink); font-size: 12px; overflow: hidden; text-overflow: ellipsis; }
.cyrus-root .pf-t small { font-size: 10.5px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; }
.cyrus-root .pf-dot { width: 7px; height: 7px; border-radius: 50%; margin-left: auto; flex: none; background: var(--muted); }
