/**
 * The change request a scoped edit sends (the prompt half of a scoped build): the user's words plus what the part may
 * change and the interfaces it must keep. The file guard (guardScopedResult) is the other half, applied to the result.
 */
export function scopedChangeRequest(spec: Pick<ModSpecV2, "modules">, plan: ScopedPlan, text: string): string {
  const t = text.trim().slice(0, 4000);
  if (plan.scope.kind === "whole") return t;
  const m = spec.modules.find((x) => x.id === (plan.scope as { id: string }).id)!;
  const lines = [
    t, "", `SCOPE: change ONLY the part "${m.title}" (module ${m.id}).`,
    `It may change: designs ${plan.may.designs.join(", ") || "none"}; assets ${plan.may.assets.join(", ") || "none"}; settings under ${plan.may.configPrefixes.join(", ") || "none"}${plan.may.files.length ? `; files under ${plan.may.files.join(", ")}` : ""}.`,
    ...(plan.interfaces.length ? [`Read-only interfaces it may use: ${plan.interfaces.map((i) => `${i.title} (${i.provides.join(", ") || "nothing"})`).join("; ")}.`] : []),
    ...(plan.dependents.length ? [`Keep these working, other parts use them: ${plan.dependents.map((d) => `${d.module} uses ${d.uses.join(", ")}`).join("; ")}.`] : []),
    "Do not add, remove or edit anything in any other part.",
  ];
  return lines.join("\n").slice(0, 6000);
}
EOF
