"use client";
// v8 structure on the project page: the mod's parts as a tree (per-part revision, Test Flight, tokens), the
// dependency view, and "Edit this part" vs "Edit whole mod". A mod suite (ModSpec v2, CYRUS_MOD_SUITES) shows its
// modules; any other mod shows the parts derived from its build (one module). Distinct from Mod Packs (several mods).
import { useMemo, useState } from "react";
import { dagLayers, partHref, type Part } from "@/lib/cyrus/structure/parts";
import { PartIcon } from "@/components/cyrus/cosmos/PartFan";

export type PartPlanView = { may: string[]; readOnly: string[]; protects: string; request: string; contextChars: number };
export type SuiteView = {
  suite: boolean;
  namespace: string | null;
  parts: Part[];
  whole: { flight: string; tokens: number; lastFlightSeq: number | null } | null;
  checks: { level: "ok" | "warn" | "bad"; text: string }[];
  plans: Record<string, PartPlanView>;
  budget: { label: string; value: number; max: number; measured: boolean; note?: string }[];
  /** CYRUS_MOD_SUITES on: scoped edits can be sent (as a scoped change request) */
  editable: boolean;
};

const FLIGHT: Record<string, [string, string]> = { passed: ["cx-ok", "passed"], failed: ["cx-bad", "failed"], stale: ["cx-wait", "changed since its flight"], none: ["", "not flown"] };
const n = (x: number) => x.toLocaleString("en-US");

export function ModuleTree({ view, buildId, mcVersion, studioBase }: { view: SuiteView; buildId: string; mcVersion: string; studioBase: string }) {
  const first = view.parts.find((p) => p.kind !== "code") ?? view.parts[0];
  const [sel, setSel] = useState<string | null>(first?.id ?? null);
  const [scope, setScope] = useState<"part" | "whole">("part");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const part = view.parts.find((p) => p.id === sel) ?? null;
  const plan = part ? view.plans[part.id] : undefined;
  const layers = useMemo(() => (view.suite ? dagLayers(view.parts) : []), [view]);
  const pos = useMemo(() => {
    const m = new Map<string, { x: number; y: number }>();
