                  {msg ? <p className="cx-muted" role="status" style={{ fontSize: 12.5, margin: "8px 0 0" }}>{msg}</p> : null}
                  <div className="cx-mt-stats">
                    <div><span>Test Flight</span><b>{FLIGHT[part.status ?? "none"][1]}</b><small>flies this part + its dependencies</small></div>
                    <div><span>Whole mod</span><b>{FLIGHT[view.whole?.flight ?? "none"][1]}</b><small>{n(view.whole?.tokens ?? 0)} tokens on whole-mod builds</small></div>
                  </div>
                  {view.budget.length ? (
                    <div className="cx-mt-budget">
                      {view.budget.map((b) => <div key={b.label}><span>{b.label} <b>{n(b.value)} / {n(b.max)}</b>{b.measured ? "" : " (estimate)"}</span><i><em style={{ width: `${Math.min(100, (b.value / b.max) * 100)}%` }} /></i></div>)}
                    </div>
                  ) : null}
                </>
              ) : <p className="cx-muted" style={{ fontSize: 13 }}>{part.detail}. Describe a change in the studio to change it.</p>}
            </>
          ) : null}
        </div>
      </div>
    </div>
  );
