          <div className="cx-mt-dag" aria-label="How the parts connect">
            <svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden>
              {view.parts.flatMap((p) => (p.dependsOn ?? []).map((d) => {
                const a = pos.get(d), b = pos.get(p.id);
                if (!a || !b) return null;
                const hot = sel === p.id || sel === d;
                return <path key={`${d}>${p.id}`} className={hot ? "on" : ""} d={`M${a.x} ${a.y} C ${(a.x + b.x) / 2} ${a.y}, ${(a.x + b.x) / 2} ${b.y}, ${b.x} ${b.y}`} />;
              }))}
            </svg>
            {view.parts.map((p) => {
