            </div>
          </div>
        ) : null}

        <div className="cx-mt-side">
          {part ? (
            <>
              <div className="cx-eyebrow">{view.suite ? `Part · ${part.kind}` : "Part"}</div>
              <h3 className="cx-h2" style={{ margin: "2px 0 8px" }}>{part.label}</h3>
              {(() => { const h = partHref(buildId, part); return h ? <a className="cx-btn cx-btn-sm" href={h.replace("/dashboard/cyrus", studioBase)}>Open {part.studio ? "in its studio" : "the files"}</a> : null; })()}
              {view.suite ? (
                <>
                  <div className="cx-seg" role="group" aria-label="Scope" style={{ margin: "14px 0 10px" }}>
                    <button type="button" aria-pressed={scope === "part"} onClick={() => setScope("part")}>Edit this part</button>
                    <button type="button" aria-pressed={scope === "whole"} onClick={() => setScope("whole")}>Edit whole mod</button>
                  </div>
                  <textarea className="cx-textarea" rows={3} value={text} onChange={(e) => setText(e.target.value)} maxLength={4000} aria-label="Describe the change" placeholder={scope === "part" ? `Change ${part.label} only…` : "Change anything in the mod…"} />
                  {scope === "part" && plan ? (
                    <div className="cx-mt-scope">
                      <div><b className="ok">May change</b> {plan.may.join(", ") || "nothing yet"}</div>
                      {plan.readOnly.length ? <div><b>Sees only the interfaces of</b> {plan.readOnly.join("; ")}</div> : null}
                      <div><b>Protected</b> {plan.protects}</div>
                    </div>
                  ) : <div className="cx-mt-scope"><div><b>Whole mod</b> every part may change; the whole mod is flown again.</div></div>}
                  <button type="button" className="cx-btn cx-btn-energy" disabled={!view.editable || busy || !text.trim()} onClick={send}>{busy ? "Starting…" : scope === "part" ? "Build this part" : "Build whole mod"}</button>
                  {!view.editable ? <p className="cx-faint" style={{ fontSize: 12, margin: "8px 0 0" }}>Scoped builds are switched off here.</p> : null}
                  {msg ? <p className="cx-muted" role="status" style={{ fontSize: 12.5, margin: "8px 0 0" }}>{msg}</p> : null}
                  <div className="cx-mt-stats">
                    <div><span>Test Flight</span><b>{FLIGHT[part.status ?? "none"][1]}</b><small>flies this part + its dependencies</small></div>
                    <div><span>Whole mod</span><b>{FLIGHT[view.whole?.flight ?? "none"][1]}</b><small>{n(view.whole?.tokens ?? 0)} tokens on whole-mod builds</small></div>
                  </div>
                  {view.budget.length ? (
                    <div className="cx-mt-budget">
                      {view.budget.map((b) => <div key={b.label}><span>{b.label} <b>{n(b.value)} / {n(b.max)}</b>{b.measured ? "" : " (estimate)"}</span><i><em style={{ width: `${Math.min(100, (b.value / b.max) * 100)}%` }} /></i></div>)}
                    </div>
