.cx-app .cx-mt-dot.cx-ok { background: var(--cx-ok); box-shadow: 0 0 8px var(--cx-ok); }
.cx-app .cx-mt-dot.cx-wait { background: var(--cx-warn); box-shadow: 0 0 8px var(--cx-warn); }
.cx-app .cx-mt-dot.cx-bad { background: var(--cx-bad); box-shadow: 0 0 8px var(--cx-bad); }
.cx-app .cx-mt-dag { position: relative; min-height: 340px; border: 1px solid var(--cx-line); border-radius: 14px; padding-bottom: 70px; }
.cx-app .cx-mt-dag svg { position: absolute; inset: 0 0 70px 0; width: 100%; height: calc(100% - 70px); }
.cx-app .cx-mt-dag path { fill: none; stroke: var(--cx-line-2); stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.cx-app .cx-mt-dag path.on { stroke: var(--cx-violet); stroke-width: 2.2; }
.cx-app .cx-mt-node { position: absolute; translate: -50% -50%; display: flex; align-items: center; gap: 7px; padding: 7px 11px; border-radius: 11px; border: 1px solid var(--cx-line-2); background: var(--cx-bg-2); color: inherit; font-size: 12.5px; white-space: nowrap; cursor: pointer; max-width: 46%; overflow: hidden; text-overflow: ellipsis; }
.cx-app .cx-mt-dag .cx-mt-node { top: 0; }
.cx-app .cx-mt-node.on { border-color: transparent; background: linear-gradient(var(--cx-bg-2), var(--cx-bg-2)) padding-box, var(--cx-energy) border-box; box-shadow: 0 0 26px -6px rgba(139,92,255,.6); }
.cx-app .cx-mt-checks { position: absolute; left: 12px; right: 12px; bottom: 10px; display: grid; gap: 4px; font-size: 12.5px; }
.cx-app .cx-mt-check { display: flex; gap: 8px; align-items: baseline; }
.cx-app .cx-mt-side { min-width: 0; }
.cx-app .cx-mt-scope { margin: 10px 0 12px; font-size: 12.5px; display: grid; gap: 5px; color: var(--cx-ink-3); }
.cx-app .cx-mt-scope b { color: var(--cx-ink); font-weight: 600; }
.cx-app .cx-mt-scope b.ok { color: var(--cx-ok); }
.cx-app .cx-mt-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 14px; }
.cx-app .cx-mt-stats div { border: 1px solid var(--cx-line); border-radius: 12px; padding: 9px 10px; display: grid; font-size: 12px; }
.cx-app .cx-mt-stats span { color: var(--cx-ink-3); }
.cx-app .cx-mt-stats small { color: var(--cx-ink-4); }
.cx-app .cx-mt-budget { display: grid; gap: 8px; margin-top: 12px; font-size: 12px; color: var(--cx-ink-3); }
.cx-app .cx-mt-budget i { display: block; height: 6px; border-radius: 6px; background: var(--cx-glass-2); overflow: hidden; margin-top: 3px; }
.cx-app .cx-mt-budget em { display: block; height: 100%; background: var(--cx-energy); }
@media (max-width: 1100px) { .cx-app .cx-mt-grid.suite { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } .cx-app .cx-mt-grid.suite .cx-mt-dag { grid-column: 1 / -1; order: 3; } }
@media (max-width: 860px) { .cx-app .cx-mt-grid, .cx-app .cx-mt-grid.suite { grid-template-columns: minmax(0, 1fr); } .cx-app .cx-mt-dag { min-height: 380px; } .cx-app .cx-mt-node { font-size: 11.5px; padding: 6px 8px; } }
EOF
echo ok

