p='app/dashboard/cyrus/app/projects/[rootId]/page.tsx'; s=open(p).read()
s=s.replace('import { studioPlanOf } from "@/lib/cyrus/studios/deps";','''import { studioPlanOf } from "@/lib/cyrus/studios/deps";
import { ModuleTree, type SuiteView } from "@/components/cyrus/app/ModuleTree";
import { modSuitesOn, planScopedChange, scopedChangeRequest, suiteBudget, suiteStatus, validateModSpecV2, validateModules, type DesignRef, type RevisionLite, type ScopedPlan } from "@/lib/cyrus/engine-core/modules";
import { SUITE_KIND_LIMITS } from "@/lib/cyrus/designer/gameplay/spec";
import { partsOfBuild, partsOfSuite } from "@/lib/cyrus/structure/parts";''')
a='''  const byId = new Map(servers.map((s) => [s.id, s]));'''
assert a in s
s=s.replace(a,'''  const suiteView = await suiteViewOf(engine, head);
'''+a,1)
a='''        <Card title="Builds" icon={<IconFlight />} className="cx-s8" aside="newest first">'''
assert a in s
s=s.replace(a,'''        {suiteView.parts.length ? (
          <Card title={suiteView.suite ? "Parts of this mod suite" : "Parts of this mod"} icon={<IconStack />} className="cx-s12" aside={suiteView.suite ? `${suiteView.parts.length} parts` : undefined}>
            <ModuleTree view={suiteView} buildId={target} mcVersion={(head ?? latest).mcVersion} studioBase={studioBase} />
          </Card>
        ) : null}

'''+a)
s+='''
/**
 * v8 structure: the parts card. A suite (head revision spec is ModSpec v2) shows its modules with per-part revision,
 * Test Flight and spend (derived from the revision chain), cross-reference checks, scoped plans and the size budget;
 * any other mod shows the parts derived from its head build.
 */
async function suiteViewOf(engine: { id: string; headRevisionId: string | null } | null, head: Parameters<typeof partsOfBuild>[0] & { result?: { assets?: { designs?: { name: string; kind?: string }[] } | null } | null } | null): Promise<SuiteView> {
  const designs: DesignRef[] = (head?.result?.assets?.designs ?? []).map((d) => ({ id: d.name, kind: d.kind ?? "item" }));
  const plain: SuiteView = { suite: false, namespace: null, parts: partsOfBuild(head), whole: null, checks: [], plans: {}, budget: [], editable: false };
  if (!engine?.headRevisionId) return plain;
  const headRev = await cyrusDb.cyrusRevision.findUnique({ where: { id: engine.headRevisionId }, select: { spec: true } }).catch(() => null);
  if ((headRev?.spec as { schemaVersion?: unknown } | null)?.schemaVersion !== 2) return plain;
  const v = validateModSpecV2(headRev!.spec, { designs });
  if (!v.ok) return { ...plain, checks: v.errors.slice(0, 4).map((e) => ({ level: "bad" as const, text: e.message })) };
  const spec = v.spec;
  const revs = await cyrusDb.cyrusRevision.findMany({ where: { projectId: engine.id }, orderBy: { seq: "asc" }, take: 500, select: { seq: true, status: true, engine: true } }).catch(() => []);
  const status = suiteStatus(spec, revs as unknown as RevisionLite[]);
  const x = validateModules(spec, designs);
  const refs = spec.modules.reduce((n, m) => n + m.uses.length + m.dependsOn.length, 0);
  const checks: SuiteView["checks"] = [
    ...(x.errors.length ? [] : [{ level: "ok" as const, text: `Cross-references: ${refs} links between parts, all inside ${spec.namespace}. No cycles.` }]),
    ...x.errors.slice(0, 3).map((e) => ({ level: "bad" as const, text: e.message })),
    ...x.warnings.slice(0, 2).map((w) => ({ level: "warn" as const, text: w.message })),
  ];
  const plans: SuiteView["plans"] = {};
  for (const m of spec.modules) {
    const p = planScopedChange(spec, { kind: "module", id: m.id }, designs) as ScopedPlan;
    plans[m.id] = {
      may: [...p.may.designs.map((d) => `${d}.json`), ...(p.may.assets.length ? [`${p.may.assets.length} asset${p.may.assets.length === 1 ? "" : "s"}`] : []), ...p.may.configPrefixes.map((c) => `${c}* settings`)],
      readOnly: p.interfaces.map((i) => `${i.title} (${i.provides.map((q) => q.split(":")[1]).join(", ") || "nothing"})`),
      protects: "every other part. If the build touches them, your version is kept and you are told.",
      request: scopedChangeRequest(spec, p, "").trim(),
      contextChars: p.contextChars,
    };
  }
  return { suite: true, namespace: spec.namespace, parts: partsOfSuite(spec, status.modules), whole: status.whole, checks, plans, budget: suiteBudget(designs, SUITE_KIND_LIMITS), editable: modSuitesOn() };
}
'''
open(p,'w').write(s)
EOF
