input.content:
// Cyrus r45 (v8 structure) screenshots: seed the devhost THROWAWAY database for usr_studio_all (run AFTER
// scripts/cyrus/studio-fixtures.ts) with one mod suite "Moth King Saga": a succeeded build whose assets list designs of
// every kind, textures, sounds, a creature and settings, plus a project whose head revision is a ModSpec v2 with six
// modules and a revision chain carrying scope / module fingerprints / tokens (so per-part revisions, flights and spend
// show). Needs CYRUS_MOD_SUITES=1 (the store accepts v2 only then). Fixture data for screenshots only.
// Refuses to run against anything but devhost's wt_* database.
//   devhost env set CYRUS_MOD_SUITES=1 && devhost run -- npx tsx scripts/cyrus/structure-fixtures.ts
import { db } from "../../lib/db";
import { cyrusDb } from "../../lib/cyrus/db";
import { createProject, addRevision } from "../../lib/cyrus/engine-core/store";
import { moduleFingerprints, type DesignRef, type ModSpecV2 } from "../../lib/cyrus/engine-core/modules";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const USER = "usr_studio_all";
const V = "1.21.11";
const ID = "mbsuitemoth";
const ago = (min: number) => new Date(Date.now() - min * 60_000);
const sha = (c: string) => c.repeat(64).slice(0, 64);

async function main() {
  if (!(await db.user.findUnique({ where: { id: USER } }))) throw new Error("run scripts/cyrus/studio-fixtures.ts first");
  await cyrusDb.cyrusProject.deleteMany({ where: { rootBuildId: ID } }).catch(() => undefined);
  await cyrusDb.modBuild.deleteMany({ where: { id: ID } });
  const d = (name: string, kind?: string) => ({ name, version: "1", specSha256: sha("a"), compileHash: sha("b"), serviceAgreed: true, configVersion: 1, settings: 6, abilities: 1, ...(kind ? { kind } : {}) });
  const designs = [d("frost_blade"), d("frost_lantern"), d("rime_bow"), d("moth_king", "boss"), d("swarm_wave", "encounter"), d("moth_pact", "quest"), d("hermit_shop", "menu"), d("saga_hud", "hud"), d("lantern_glow", "motion")];
  const result = {
    summary: { tagline: "A frost-and-moth saga", text: "", howToUse: [], limitations: [], changes: "" },
    commands: [], permissions: [], warnings: [], repairs: 0, queuePosition: 0, events: [], safety: { verdict: "pass", findings: [] },
    config: Array.from({ length: 48 }, (_, i) => ({ key: `k${i}`, description: "", default: "1" })),
    files: [...Array.from({ length: 31 }, (_, i) => ({ path: `src/main/java/nx/saga/C${i}.java`, size: 900 })), ...designs.map((x) => ({ path: `assets/designs/${x.name}.json`, size: 1200 }))],
    assets: {
      status: "unhosted", namespace: "nx_4f2a91c0", projectId: "fx", revisionId: null,
      textures: ["frost_blade", "frost_lantern", "rime_bow", "moth_wing", "cocoon"].map((n) => ({ name: n, model: `nx_4f2a91c0:${n}`, specSha256: sha("c"), pngSha256: sha("d"), quality: "pass" })),
      sounds: ["moth_hurt", "moth_death", "quest_start"].map((set) => ({ set, event: "play", key: `nx_4f2a91c0:${set}.play`, subtitle: set, role: "sfx", category: "hostile", variants: 2, quality: "pass", specSha256: sha("e") })),
      soundRender: "off",
      creatures: [{ name: "moth", key: "nx_4f2a91c0:moth", specSha256: sha("f"), bbmodelSha256: sha("0"), pngSha256: sha("1"), quality: "pass", bones: 9, cubes: 14, clips: ["idle", "fly"], sounds: {}, spec: {} }],
      dropped: [], designs, pack: null, loader: null, notices: [],
    },
  };
  await cyrusDb.modBuild.create({ data: { id: ID, userId: USER, mcVersion: V, prompt: "Moth King saga: frost weapons, moth creatures, a five-step quest line, the Moth King boss, a hermit shop and a saga HUD.", pluginName: "MothKingSaga", version: "1.4.0", status: "succeeded", jarName: "MothKingSaga-1.4.0.jar", createdAt: ago(600), finishedAt: ago(590), result, cyrus: { title: "Moth King Saga", category: "creatures" } } as never });

  const m = (id: string, kind: string, title: string, o: Partial<ModSpecV2["modules"][number]> = {}) => ({ id, kind, title, dependsOn: [], requirementIds: [], assets: [], designs: [], files: [], provides: [], uses: [], ...o });
  const spec = {
    schemaVersion: 2, game: "minecraft", target: { version: V }, namespace: "nx_4f2a91c0", summary: "Moth King saga: frost weapons, moth creatures, a quest line and a boss", routes: ["plugin"],
    requirements: [{ id: "REQ-1", text: "three frost weapons", priority: "must" }, { id: "REQ-2", text: "moth creatures", priority: "must" }, { id: "REQ-3", text: "the moth pact quest line", priority: "must" }],
    nonGoals: [], constraints: [], tests: [], install: { side: "server", restartRequired: true, clientSteps: [], notes: [] },
