import { partsOfBuild, partsOfSuite, partHref, dagLayers } from "../lib/cyrus/structure/parts";
import { scopedChangeRequest } from "../lib/cyrus/engine-core/modules";
import { syntheticSuite, SUITE_NS } from "../scripts/cyrus/suite-synthetic";

describe("parts (Forge sub-branches + project page)", () => {
  it("a plain build gets parts derived from what it shipped", () => {
    const b = { result: { files: [{ path: "src/A.java", size: 1 }], config: [{ key: "a", description: "", default: "1" }], assets: { designs: [{ name: "x" }, { name: "q", kind: "quest" }, { name: "b", kind: "boss" }], textures: [{ name: "t" }], sounds: [{ set: "s", event: "a" }, { set: "s", event: "b" }], datapacks: [] } } } as never;
    const p = partsOfBuild(b);
    assert.deepEqual(p.map((x) => x.kind), ["items", "quests", "bosses", "textures", "sounds", "config", "code"]);
    assert.equal(p.find((x) => x.kind === "sounds")!.count, 1, "sound sets, not events");
    assert.match(partHref("b1", p[1])!, /\/studio\/menus\?part=quests&tab=quests/);
    assert.equal(partHref("b1", p[0], { items: false }), null, "switched-off studio: no link");
    assert.match(partHref("b1", p.at(-1)!)!, /tab=files/);
    assert.deepEqual(partsOfBuild(null), []);
  });
  it("a suite gets one part per module, layered by dependencies", () => {
    const s = suite();
    const parts = partsOfSuite(s);
    assert.deepEqual(parts.map((x) => x.id), ["weapons", "moths", "pact"]);
    assert.match(partHref("b1", parts[2])!, /module=pact/);
    assert.deepEqual(dagLayers(parts), [["weapons"], ["moths"], ["pact"]]);
    const plan = planScopedChange(s, { kind: "module", id: "pact" }, designs) as ScopedPlan;
    const req = scopedChangeRequest(s, plan, "Add a sixth step");
    assert.match(req, /SCOPE: change ONLY the part "The Moth Pact"/);
    assert.match(req, /Do not add, remove or edit anything in any other part/);
  });
  it("the large synthetic suite fits SUITE limits only", () => {
    const big = syntheticSuite(4, 4);
    assert.equal(big.designs.length, 80);
    const v = validateGameplay(big.designs, { version: "1.21.11", namespace: SUITE_NS, limits: SUITE_KIND_LIMITS });
    assert.ok(v.ok, JSON.stringify(v.errors.slice(0, 3)));
    assert.equal(validateGameplay(big.designs, { version: "1.21.11", namespace: SUITE_NS }).ok, false);
  });
});
EOF
