const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/struct";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".studio-tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, url, { view = "desktop", theme = "dark", wait = "body", act, tall = false } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: tall ? (v.mobile ? 2400 : 1500) : v.height }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  const res = await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector(wait, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {}); }
  await page.waitForTimeout(2500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1500);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
const M = "mbsuitemoth";
await shot("struct-forge-dark", `/dashboard/cyrus/${M}`, { wait: ".pf" });
await shot("struct-forge-light", `/dashboard/cyrus/${M}`, { wait: ".pf", theme: "light" });
await shot("struct-forge-phone", `/dashboard/cyrus/${M}`, { wait: ".pf", view: "phone" });
await shot("struct-project-dark", `/dashboard/cyrus/app/projects/${M}`, { wait: ".cx-mt", tall: true, act: async (p) => { await p.locator(".cx-mt").scrollIntoViewIfNeeded(); } });
await shot("struct-project-whole", `/dashboard/cyrus/app/projects/${M}`, { wait: ".cx-mt", tall: true, act: async (p) => { await p.getByRole("button", { name: "Edit whole mod" }).click(); } });
await shot("struct-project-phone", `/dashboard/cyrus/app/projects/${M}`, { wait: ".cx-mt", view: "phone", tall: true });
await shot("struct-project-light", `/dashboard/cyrus/app/projects/${M}`, { wait: ".cx-mt", theme: "light", tall: true });
await shot("struct-studio-crumb", `/dashboard/cyrus/${M}/studio/menus?part=quests&module=pact&tab=quests`, { wait: ".cys-crumbs" });
await shot("struct-newmod-dark", "/dashboard/cyrus/app/new", { wait: ".cx-card", tall: true });
await shot("struct-newmod-phone", "/dashboard/cyrus/app/new", { wait: ".cx-card", view: "phone", tall: true });
await browser.close();

